// Trigger Otorisasi Manual & Buat Sheet Otomatis jika belum ada
function triggerAuthPrompt() {
  ensureAllSheetsExist();
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheetCount = ss.getSheets().length;
  if (typeof DriveApp !== 'undefined') {
    var folders = DriveApp.getFolders();
  }
  Logger.log("Otorisasi & pembuatan sheet berhasil! Jumlah sheet: " + sheetCount);
}

function ensureAllSheetsExist() {
  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    if (!ss) return;

    var requiredSheets = {
      'Rumah Dinas': [
        'id', 'NAMA', 'NIP', 'PANGKATGOLRUANG', 'JABATAN', 'ORGANISASI_UNIT_KERJA',
        'JENIS_BARANGNAMA_BARANG', 'KODE_BARANG', 'NIBAR', 'KONDISI_BANGUNAN_BKBRB',
        'KONTRUKSI_BANGUNAN', 'LUAS_LANTAI', 'LETAKLOKASI_ALAMAT', 'DOKUMEN_GEDUNG',
        'LUAS', 'STATUS_TANAH', 'ASAL_USUL', 'NOMER_SERTIFIKAT', 'PENGGUNAAN',
        'LINK_BA', 'LINK_PI', 'LINK_DP', 'LINK_DT', 'LINK_MD', 'SATUAN',
        'HARGA_SATUAN', 'NILAI_PEROLEHAN', 'CARA_PEROLEHAN', 'TANGGAL_PEROLEHAN', 'KETERANGAN'
      ]
    };

    for (var name in requiredSheets) {
      var sheet = ss.getSheetByName(name);
      if (!sheet) {
        sheet = ss.insertSheet(name);
        var headers = requiredSheets[name];
        sheet.appendRow(headers);
        sheet.getRange(1, 1, 1, headers.length).setFontWeight('bold').setBackground('#f3f3f3');
        console.log("Berhasil membuat sheet otomatis: " + name);
      }
    }
  } catch (err) {
    console.error("ensureAllSheetsExist Error: " + err.message);
  }
}

// Main Router
function doGet(e) {
  try {
    ensureAllSheetsExist();
    upgradeDatabaseColumns();
  } catch (err) {
    console.error("doGet upgrade error: " + err.message);
  }
  return HtmlService.createTemplateFromFile('Index').evaluate()
    .setTitle('Sistem Aset Sementara & Cetak BA')
    .addMetaTag('viewport', 'width=device-width, initial-scale=1')
    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL);
}

function upgradeDatabaseColumns() {
  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    if (!ss) return;
    var sheets = ['Kendaraan', 'Peralatan', 'Peralatan dan Mesin', 'Alkes', 'Rumah Dinas'];
    var newCols = ['LINK_BA', 'LINK_PI', 'LINK_DP', 'LINK_DT', 'LINK_MD', 'SATUAN', 'HARGA_SATUAN', 'NILAI_PEROLEHAN', 'CARA_PEROLEHAN', 'TANGGAL_PEROLEHAN', 'KETERANGAN'];

    sheets.forEach(function (sheetName) {
      var sheet = ss.getSheetByName(sheetName);
      if (sheet && sheet.getLastColumn() > 0) {
        var headerRow = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];
        newCols.forEach(function (col) {
          if (headerRow.indexOf(col) === -1) {
            sheet.getRange(1, sheet.getLastColumn() + 1).setValue(col);
          }
        });
        
        // Tambahan khusus Alkes
        if (sheetName === 'Alkes') {
          if (headerRow.indexOf('JADWAL_KALIBRASI') === -1) {
            sheet.getRange(1, sheet.getLastColumn() + 1).setValue('JADWAL_KALIBRASI');
          }
        }
      }
    });
  } catch (e) {
    console.error("upgradeDatabaseColumns Error: " + e.message);
  }
}

// SHA-256 Hashing Algorithm
function hashPassword(password) {
  var digest = Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, password);
  var hex = '';
  for (var i = 0; i < digest.length; i++) {
    var byteVal = digest[i];
    if (byteVal < 0) byteVal += 256;
    var byteString = byteVal.toString(16);
    if (byteString.length == 1) byteString = '0' + byteString;
    hex += byteString;
  }
  return hex;
}

