// API: Get Print Templates
function getTemplates(token) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getSheetByName('TemplateDokumen');
  if (!sheet || sheet.getLastRow() <= 1) return { success: true, data: [] };

  var data = sheet.getRange(2, 1, sheet.getLastRow() - 1, sheet.getLastColumn()).getValues();
  var map = getColumnMap(sheet);

  var result = data.map(function (row) {
    var obj = {};
    for (var key in map) {
      obj[key] = row[map[key] - 1];
    }
    // Ekstrak tag dengan aman
    try {
      obj.tags = obj.tags ? JSON.parse(obj.tags) : [];
    } catch (e) {
      obj.tags = [];
    }
    return obj;
  });

  return { success: true, data: result };
}

// API: Save Edited Template
function saveTemplate(token, id, isiTemplate) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getSheetByName('TemplateDokumen');
  if (!sheet) return { success: false, message: 'Template table not found.' };

  var data = sheet.getRange(2, 1, sheet.getLastRow() - 1, 1).getValues();
  var map = getColumnMap(sheet);

  for (var i = 0; i < data.length; i++) {
    if (data[i][0] === id) {
      sheet.getRange(i + 2, map['isi_template']).setValue(isiTemplate);
      logAction(session.username, 'EDIT_TEMPLATE', 'Mengubah template ' + id);
      return { success: true };
    }
  }

  return { success: false, message: 'Template tidak ditemukan.' };
}
// ==========================================
// = FITUR BARU: UPLOAD MASTER TEMPLATE DOCX
// = powered gas by agunk & code puzzle
// ==========================================
function uploadTemplateFileDocx(token, id, fileObj) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message };

  try {
    var blob = Utilities.newBlob(Utilities.base64Decode(fileObj.base64.split(',')[1]), fileObj.mimeType, fileObj.fileName);

    var file;
    var isExcel = fileObj.fileName.toLowerCase().endsWith('.xlsx') || fileObj.mimeType.indexOf('spreadsheetml') !== -1;
    var targetMime = isExcel ? MimeType.GOOGLE_SHEETS : MimeType.GOOGLE_DOCS;

    try {
      // Mencoba syntax Drive API v3 (Terbaru)
      file = Drive.Files.create({
        name: fileObj.fileName,
        mimeType: targetMime
      }, blob);
    } catch (err3) {
      try {
        // Fallback jika API yang aktif adalah v2
        file = Drive.Files.insert({
          title: fileObj.fileName,
          mimeType: targetMime
        }, blob);
      } catch (err2) {
        return { success: false, message: 'Error Drive API: ' + err3.message + ' / ' + err2.message };
      }
    }

    var docId = file.id;

    // --- UBAH: Pindahkan file ke dalam sub-folder 'MASTER TEMPLATE DOKUMEN' ---
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var ssFile = DriveApp.getFileById(ss.getId());
    var parentFolder = ssFile.getParents().next();
    var folders = parentFolder.getFoldersByName("MASTER TEMPLATE DOKUMEN");
    var templateFolder = folders.hasNext() ? folders.next() : parentFolder.createFolder("MASTER TEMPLATE DOKUMEN");

    var docFile = DriveApp.getFileById(docId);
    docFile.moveTo(templateFolder);
    // -------------------------------------------------------------------

    var uniqueTags = [];
    if (!isExcel) {
      var doc = DocumentApp.openById(docId);
      var bodyText = doc.getBody().getText();

      // Scan format tag: {{nama_tag}} (Mendukung huruf besar maupun kecil)
      var tags = bodyText.match(/\{\{[a-zA-Z0-9_]+\}\}/gi) || [];
      uniqueTags = [...new Set(tags)];
    } else {
      uniqueTags = ['Template Excel / Spreadsheet'];
    }

    // Save ID Google Docs ke database
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheet = ss.getSheetByName('TemplateDokumen');
    var map = getColumnMap(sheet);

    // Auto-tambah kolom tags jika belum ada di database
    if (map['tags'] === undefined) {
      sheet.getRange(1, sheet.getLastColumn() + 1).setValue('tags');
      map = getColumnMap(sheet);
    }

    var data = sheet.getDataRange().getValues();
    for (var i = 0; i < data.length; i++) {
      if (data[i][0] === id) {
        // --- UBAH: Hapus file lama di Drive agar tidak menumpuk ---
        var oldDocId = data[i][map['isi_template'] - 1]; // FIX 0-BASED INDEX
        if (oldDocId && oldDocId.toString().length >= 25 && oldDocId.indexOf('<') === -1) {
          try {
            var oldFile = DriveApp.getFileById(oldDocId);
            oldFile.setTrashed(true);
          } catch (e) {
            // Abaikan jika file lama tidak ditemukan atau tidak ada akses
          }
        }
        // ----------------------------------------------------------

        sheet.getRange(i + 1, map['isi_template']).setValue(docId);
        sheet.getRange(i + 1, map['tags']).setValue(JSON.stringify(uniqueTags));
        logAction(session.username, 'UPLOAD_DOCX', 'Upload template master ID: ' + id);
        break;
      }
    }

    return { success: true, tags: uniqueTags, docId: docId };
  } catch (e) {
    return { success: false, message: e.message };
  }
}

// API: Generate Excel Spreadsheet untuk Daftar Peminjam Peralatan
function generateExcelDaftarPeminjam(token, templateId, payload) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  try {
    if (!templateId || templateId === 'TEMPLATE_BARU_KOSONG') {
      return { success: false, message: 'Template ID tidak valid atau belum diatur.' };
    }

    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheetName = getSheetNameByType(payload.type);
    var shAset = ss.getSheetByName(sheetName);
    var mapAset = getColumnMap(shAset);
    var dataAset = shAset.getRange(2, 1, shAset.getLastRow() - 1, shAset.getLastColumn()).getValues();

    // 1. Fetch Data berdasarkan ID yang dipilih
    var resultData = [];
    var noUrut = 1;
    for (var i = 0; i < dataAset.length; i++) {
      var row = dataAset[i];
      var id = row[mapAset['id'] - 1];
      // Hanya ekspor data yang di-ceklis oleh user
      if (payload.assetIds.indexOf(id) !== -1) {
        // Tambahkan tanda petik tunggal (') di NIBAR untuk mencegah angka 0 di depan hilang
        var nibarOri = row[mapAset['NOMOR_REGISTER'] - 1] || row[mapAset['NIBAR'] - 1] || '-';
        var nibarSafe = nibarOri !== '-' ? "'" + nibarOri : '-';

        resultData.push([
          noUrut++,                                    // 1: No
          row[mapAset['JENIS_NAMA_BARANG'] - 1] || row[mapAset['NAMA_BARANG'] - 1] || '-', // 2: Nama Barang
          nibarSafe,                                   // 3: Nibar (Aman dari 0 hilang)
          row[mapAset['MERK_TYPE'] - 1] || '-',               // 4: Merk / Type
          row[mapAset['UKURAN_CC'] - 1] || '-',               // 5: Ukuran / CC
          row[mapAset['TAHUN_PEROLEHAN'] - 1] || row[mapAset['TAHUN'] - 1] || '-',         // 6: Tahun Perolehan
          row[mapAset['NAMA'] - 1] || '-',                    // 7: Nama Pengguna
          row[mapAset['JABATAN'] - 1] || '-'                  // 8: Jabatan Pengguna
        ]);
      }
    }

    if (resultData.length === 0) {
      return { success: false, message: 'Tidak ada data valid yang dipilih.' };
    }

    // 2. Duplicate Spreadsheet Template
    var originalFile = DriveApp.getFileById(templateId);
    var timestamp = Utilities.formatDate(new Date(), Session.getScriptTimeZone(), "yyyyMMdd_HHmmss");
    var fileName = "Daftar_Peminjam_" + sheetName + "_" + timestamp;
    var copiedFile = originalFile.makeCopy(fileName);
    copiedFile.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);

    // 3. Inject Data
    var targetSpreadsheet = SpreadsheetApp.openById(copiedFile.getId());
    var targetSheet = targetSpreadsheet.getSheets()[0];

    // Menyisipkan baris di baris ke-7 agar template signature di bawahnya terdorong ke bawah
    targetSheet.insertRows(7, resultData.length);

    // Mengisi data mulai Baris 7, Kolom 1 sampai dengan Kolom 8 (sesuai template gambar)
    var range = targetSheet.getRange(7, 1, resultData.length, 8);
    range.setValues(resultData);

    // Menambahkan Border dan memformat huruf agar seragam
    range.setBorder(true, true, true, true, true, true, null, SpreadsheetApp.BorderStyle.SOLID)
      .setFontFamily("Arial")
      .setFontSize(10)
      .setVerticalAlignment("middle")
      .setHorizontalAlignment("center");

    var excelUrl = "https://docs.google.com/spreadsheets/d/" + copiedFile.getId() + "/export?format=xlsx";
    var sheetUrl = "https://docs.google.com/spreadsheets/d/" + copiedFile.getId() + "/edit";

    // 4. Log Document (Menyimpan riwayat ke sheet Dokumen)
    var shDoc = ss.getSheetByName('Dokumen');
    var mapDoc = getColumnMap(shDoc);
    var newDocRow = new Array(shDoc.getLastColumn()).fill('');
    var newDocId = 'DOC-' + new Date().getTime();
    newDocRow[mapDoc['id'] - 1] = newDocId;
    newDocRow[mapDoc['jenis_aset'] - 1] = sheetName;
    newDocRow[mapDoc['jenis_dokumen'] - 1] = 'Daftar Peminjam';
    newDocRow[mapDoc['tanggal_dokumen'] - 1] = new Date().toISOString().split('T')[0];
    newDocRow[mapDoc['status_print'] - 1] = 'Tercetak (Excel)';
    newDocRow[mapDoc['file_pdf_url'] - 1] = excelUrl;
    newDocRow[mapDoc['created_by'] - 1] = session.username;
    newDocRow[mapDoc['created_at'] - 1] = new Date().toISOString();
    shDoc.appendRow(newDocRow);

    logAction(session.username, 'GENERATE_EXCEL', 'Generate Daftar Peminjam Excel: ' + fileName);

    // Update LINK_DP in sheet Kendaraan / Peralatan
    if (mapAset['LINK_DP']) {
      payload.assetIds.forEach(function (assetId) {
        for (var i = 0; i < dataAset.length; i++) {
          if (dataAset[i][mapAset['id'] - 1] === assetId) {
            shAset.getRange(i + 2, mapAset['LINK_DP']).setValue(excelUrl);
            break;
          }
        }
      });
    }

    return {
      success: true,
      downloadUrl: excelUrl,
      sheetUrl: sheetUrl,
      message: 'Spreadsheet berhasil dibuat dan disiapkan untuk diunduh.'
    };

  } catch (e) {
    return { success: false, message: 'Gagal membuat Excel: ' + e.message };
  }
}

// API: Generate Excel Spreadsheet untuk Daftar Penandatangan (Pakta Integritas)
function generateExcelDaftarPenandatangan(token, templateId, payload) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  try {
    if (!templateId || templateId === 'TEMPLATE_BARU_KOSONG') {
      return { success: false, message: 'Template ID tidak valid atau belum diatur.' };
    }

    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheetName = getSheetNameByType(payload.type);
    var shAset = ss.getSheetByName(sheetName);
    var mapAset = getColumnMap(shAset);
    var dataAset = shAset.getRange(2, 1, shAset.getLastRow() - 1, shAset.getLastColumn()).getValues();

    // Load History Dokumen untuk mengecek status Pakta Integritas per Aset
    var shDoc = ss.getSheetByName('Dokumen');
    var mapDoc = getColumnMap(shDoc);
    var docData = shDoc.getRange(2, 1, shDoc.getLastRow() - 1, shDoc.getLastColumn()).getValues();
    var piStatus = {};
    for (var i = 0; i < docData.length; i++) {
      if (docData[i][mapDoc['jenis_dokumen'] - 1] === 'Pakta Integritas') {
        piStatus[docData[i][mapDoc['asset_id'] - 1]] = true;
      }
    }

    // 1. Fetch Data berdasarkan ID yang dipilih
    var resultData = [];
    var noUrut = 1;
    for (var i = 0; i < dataAset.length; i++) {
      var row = dataAset[i];
      var id = row[mapAset['id'] - 1];
      if (payload.assetIds.indexOf(id) !== -1) {
        var statusPI = piStatus[id] ? "ADA" : "TIDAK ADA";
        resultData.push([
          noUrut++,                                    // 1: No
          row[mapAset['NAMA'] - 1] || '-',             // 2: Nama
          row[mapAset['JABATAN'] - 1] || '-',          // 3: Jabatan
          row[mapAset['JENIS_NAMA_BARANG'] - 1] || row[mapAset['NAMA_BARANG'] - 1] || '-', // 4: Jenis BMD
          statusPI,                                    // 5: Pakta Integritas (ADA/TIDAK ADA)
          "-"                                          // 6: Ket
        ]);
      }
    }

    if (resultData.length === 0) {
      return { success: false, message: 'Tidak ada data valid yang dipilih.' };
    }

    // 2. Duplicate Spreadsheet Template
    var originalFile = DriveApp.getFileById(templateId);
    var timestamp = Utilities.formatDate(new Date(), Session.getScriptTimeZone(), "yyyyMMdd_HHmmss");
    var fileName = "Daftar_Penandatangan_" + sheetName + "_" + timestamp;
    var copiedFile = originalFile.makeCopy(fileName);
    copiedFile.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);

    // 3. Inject Data
    var targetSpreadsheet = SpreadsheetApp.openById(copiedFile.getId());
    var targetSheet = targetSpreadsheet.getSheets()[0];

    // Menyisipkan baris di baris ke-7 agar template signature di bawahnya terdorong ke bawah
    targetSheet.insertRows(7, resultData.length);

    // Mengisi data mulai Baris 7, Kolom 1 sampai dengan Kolom 6
    var range = targetSheet.getRange(7, 1, resultData.length, 6);
    range.setValues(resultData);

    // Menambahkan Border dan memformat huruf agar seragam
    range.setBorder(true, true, true, true, true, true, null, SpreadsheetApp.BorderStyle.SOLID)
      .setFontFamily("Arial")
      .setFontSize(10)
      .setVerticalAlignment("middle")
      .setHorizontalAlignment("center");

    var excelUrl = "https://docs.google.com/spreadsheets/d/" + copiedFile.getId() + "/export?format=xlsx";
    var sheetUrl = "https://docs.google.com/spreadsheets/d/" + copiedFile.getId() + "/edit";

    // 4. Log Document
    var newDocRow = new Array(shDoc.getLastColumn()).fill('');
    var newDocId = 'DOC-' + new Date().getTime();
    newDocRow[mapDoc['id'] - 1] = newDocId;
    newDocRow[mapDoc['jenis_aset'] - 1] = sheetName;
    newDocRow[mapDoc['jenis_dokumen'] - 1] = 'Daftar Penandatangan';
    newDocRow[mapDoc['tanggal_dokumen'] - 1] = new Date().toISOString().split('T')[0];
    newDocRow[mapDoc['status_print'] - 1] = 'Tercetak (Excel)';
    newDocRow[mapDoc['file_pdf_url'] - 1] = excelUrl;
    newDocRow[mapDoc['created_by'] - 1] = session.username;
    newDocRow[mapDoc['created_at'] - 1] = new Date().toISOString();
    shDoc.appendRow(newDocRow);

    logAction(session.username, 'GENERATE_EXCEL', 'Generate Daftar Penandatangan Excel: ' + fileName);

    // Update LINK_DT in sheet Kendaraan / Peralatan
    if (mapAset['LINK_DT']) {
      payload.assetIds.forEach(function (assetId) {
        for (var i = 0; i < dataAset.length; i++) {
          if (dataAset[i][mapAset['id'] - 1] === assetId) {
            shAset.getRange(i + 2, mapAset['LINK_DT']).setValue(excelUrl);
            break;
          }
        }
      });
    }

    return {
      success: true,
      downloadUrl: excelUrl,
      sheetUrl: sheetUrl,
      message: 'Spreadsheet berhasil dibuat dan disiapkan untuk diunduh.'
    };

  } catch (e) {
    return { success: false, message: 'Gagal membuat Excel: ' + e.message };
  }
}

// API: Generate Excel Spreadsheet untuk Master Data
function generateExcelMasterData(token, templateId, payload) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  try {
    if (!templateId || templateId === 'TEMPLATE_BARU_KOSONG') {
      return { success: false, message: 'Template ID tidak valid atau belum diatur.' };
    }

    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheetName = getSheetNameByType(payload.type);
    var shAset = ss.getSheetByName(sheetName);
    var mapAset = getColumnMap(shAset);
    var numCols = shAset.getLastColumn();
    var dataAset = shAset.getRange(2, 1, shAset.getLastRow() - 1, numCols).getValues();

    var resultData = [];
    var noUrut = 1;
    for (var i = 0; i < dataAset.length; i++) {
      var row = dataAset[i];
      var id = row[mapAset['id'] - 1];
      if (payload.assetIds.indexOf(id) !== -1) {
        var bpkbIndex = mapAset['NO_BPKB'] || 18;
        var newRow = [];
        if (sheetName === 'Rumah Dinas' && mapAset['PENGGUNAAN']) {
          bpkbIndex = mapAset['PENGGUNAAN'];
          newRow = [noUrut++];
          newRow = newRow.concat(row.slice(1, bpkbIndex));
        } else {
          newRow = row.slice(1, bpkbIndex);
          if (mapAset['NO'] && mapAset['NO'] > 1 && mapAset['NO'] - 2 < newRow.length) {
            newRow[mapAset['NO'] - 2] = noUrut++;
          }
        }
        var protectCols = ['NOMOR_REGISTER', 'NIBAR', 'KODE_BARANG', 'NO_MESIN', 'NO_RANGKA', 'NO_RANGKA_SN', 'NO_BPKB'];
        for (var j = 0; j < protectCols.length; j++) {
          var colName = protectCols[j];
          if (mapAset[colName] && mapAset[colName] > 1 && mapAset[colName] - 2 < newRow.length) {
            var val = newRow[mapAset[colName] - 2];
            if (val && !String(val).startsWith("'")) {
              newRow[mapAset[colName] - 2] = "'" + val;
            }
          }
        }
        resultData.push(newRow);
      }
    }

    if (resultData.length === 0) {
      return { success: false, message: 'Tidak ada data valid yang dipilih.' };
    }

    var originalFile = DriveApp.getFileById(templateId);
    var timestamp = Utilities.formatDate(new Date(), Session.getScriptTimeZone(), "yyyyMMdd");
    var fileName = "Master_Data_" + sheetName + "_" + timestamp;

    var ssFile = DriveApp.getFileById(ss.getId());
    var parentFolder = ssFile.getParents().next();

    var assetCategoryFolder = getFolderByType(payload.type);
    var rootReportFolderIter = parentFolder.getFoldersByName(assetCategoryFolder);
    var rootReportFolder = rootReportFolderIter.hasNext() ? rootReportFolderIter.next() : parentFolder.createFolder(assetCategoryFolder);

    var docNameFull = "Master Data " + sheetName;
    var specificFolderIter = rootReportFolder.getFoldersByName(docNameFull);
    var specificFolder = specificFolderIter.hasNext() ? specificFolderIter.next() : rootReportFolder.createFolder(docNameFull);

    var copiedFile = originalFile.makeCopy(fileName, specificFolder);
    copiedFile.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);

    var targetSpreadsheet = SpreadsheetApp.openById(copiedFile.getId());
    var targetSheet = targetSpreadsheet.getSheets()[0];

    if (resultData.length > 0) {
      targetSheet.insertRowsAfter(4, resultData.length);
    }
    var range = targetSheet.getRange(5, 1, resultData.length, resultData[0].length);
    range.setValues(resultData);
    range.setBorder(true, true, true, true, true, true, null, SpreadsheetApp.BorderStyle.SOLID)
      .setFontFamily("Arial")
      .setFontSize(10)
      .setVerticalAlignment("middle")
      .setHorizontalAlignment("center");

    var excelUrl = "https://docs.google.com/spreadsheets/d/" + copiedFile.getId() + "/export?format=xlsx";
    var sheetUrl = "https://docs.google.com/spreadsheets/d/" + copiedFile.getId() + "/edit";

    var shDoc = ss.getSheetByName('Dokumen');
    var mapDoc = getColumnMap(shDoc);
    var newDocRow = new Array(shDoc.getLastColumn()).fill('');
    var newDocId = 'DOC-' + new Date().getTime();
    newDocRow[mapDoc['id'] - 1] = newDocId;
    newDocRow[mapDoc['jenis_aset'] - 1] = sheetName;
    newDocRow[mapDoc['jenis_dokumen'] - 1] = 'Master Data ' + sheetName;
    newDocRow[mapDoc['tanggal_dokumen'] - 1] = new Date().toISOString().split('T')[0];
    newDocRow[mapDoc['status_print'] - 1] = 'Tercetak (Excel)';
    newDocRow[mapDoc['file_pdf_url'] - 1] = excelUrl;
    newDocRow[mapDoc['created_by'] - 1] = session.username;
    newDocRow[mapDoc['created_at'] - 1] = new Date().toISOString();
    shDoc.appendRow(newDocRow);

    // Update LINK_MD in sheet Kendaraan / Peralatan
    if (mapAset['LINK_MD']) {
      for (var i = 0; i < dataAset.length; i++) {
        var id = dataAset[i][mapAset['id'] - 1];
        if (payload.assetIds.indexOf(id) !== -1) {
          shAset.getRange(i + 2, mapAset['LINK_MD']).setValue(excelUrl);
        }
      }
    }

    logAction(session.username, 'GENERATE_EXCEL', 'Generate Master Data Excel: ' + fileName);

    return {
      success: true,
      downloadUrl: excelUrl,
      sheetUrl: sheetUrl,
      message: 'Spreadsheet Master Data berhasil dibuat dan disiapkan untuk diunduh.'
    };

  } catch (e) {
    return { success: false, message: 'Gagal membuat Excel Master Data: ' + e.message };
  }
}

// API: Document Generation (Satuan & Gabungan PDF / Print)

// API: Generate Excel Spreadsheet untuk L5 Pinjam Pakai Peralatan Mesin
function generateExcelL5PinjamPakai(token, templateId, payload) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();

    // --- AUTO-FIND TEMPLATE ---
    // Cari template dari sheet TemplateDokumen jika templateId tidak valid
    var resolvedTemplateId = templateId;
    if (!resolvedTemplateId || resolvedTemplateId === 'TEMPLATE_BARU_KOSONG') {
      var shTmpl = ss.getSheetByName('TemplateDokumen');
      if (shTmpl && shTmpl.getLastRow() > 1) {
        var mapTmpl = getColumnMap(shTmpl);
        var dataTmpl = shTmpl.getRange(2, 1, shTmpl.getLastRow() - 1, shTmpl.getLastColumn()).getValues();
        for (var t = 0; t < dataTmpl.length; t++) {
          var tmplRow = dataTmpl[t];
          var jenisTemplate = String(tmplRow[mapTmpl['jenis_template'] - 1] || '');
          if (jenisTemplate.toLowerCase().indexOf('l5') !== -1 || jenisTemplate.toLowerCase().indexOf('pinjam pakai') !== -1) {
            resolvedTemplateId = tmplRow[mapTmpl['isi_template'] - 1];
            break;
          }
        }
      }
    }

    // --- GET/CREATE DESTINATION FOLDER ---
    // Cari folder 'DOKUMEN L5 PINJAM PAKAI' di dalam folder induk 'APLIKASI SI-ASET'
    var destFolder = null;
    try {
      // Cari folder induk 'APLIKASI SI-ASET' dari spreadsheet parent
      var ssFile = DriveApp.getFileById(ss.getId());
      var parentFolders = ssFile.getParents();
      var indukFolder = null;
      // Cari folder induk yang namanya mengandung 'APLIKASI SI-ASET' atau 'SI-ASET' atau 'ASET'
      while (parentFolders.hasNext()) {
        var pf = parentFolders.next();
        var pfName = pf.getName().toUpperCase();
        if (pfName.indexOf('APLIKASI') !== -1 || pfName.indexOf('SI-ASET') !== -1 || pfName.indexOf('ASET') !== -1) {
          indukFolder = pf;
          break;
        }
      }
      // Jika tidak ketemu folder induk dengan nama spesifik, gunakan parent pertama
      if (!indukFolder) {
        var ssFile2 = DriveApp.getFileById(ss.getId());
        var pf2 = ssFile2.getParents();
        if (pf2.hasNext()) {
          indukFolder = pf2.next();
        }
      }

      if (indukFolder) {
        // Cari subfolder 'DOKUMEN L5 PINJAM PAKAI' di dalam indukFolder
        var subFolders = indukFolder.getFolders();
        while (subFolders.hasNext()) {
          var sf = subFolders.next();
          if (sf.getName().toUpperCase().indexOf('DOKUMEN L5') !== -1 || sf.getName().toUpperCase().indexOf('L5 PINJAM PAKAI') !== -1) {
            destFolder = sf;
            break;
          }
        }
        // Jika belum ada, buat folder baru
        if (!destFolder) {
          destFolder = indukFolder.createFolder('DOKUMEN L5 PINJAM PAKAI');
        }
      }
    } catch (folderErr) {
      // Jika gagal cari folder, lanjut tanpa folder khusus (simpan di root)
      destFolder = null;
    }

    // --- LOAD DATA L5 ---
    var resL5 = getL5Data(token);
    if (!resL5.success) {
      return { success: false, message: resL5.message };
    }

    var allData = resL5.data;
    var resultData = [];
    var noUrut = 1;

    for (var i = 0; i < allData.length; i++) {
      var item = allData[i];
      if (payload.assetIds.indexOf(item.id) !== -1) {
        var nibarSafe = item.NIBAR && item.NIBAR !== '-' ? "'" + item.NIBAR : (item.NIBAR || '-');
        var kodeBarangSafe = item.KODE_BARANG && item.KODE_BARANG !== '-' ? "'" + item.KODE_BARANG : (item.KODE_BARANG || '-');
        var nikSafe = item.NIP && item.NIP !== '-' ? "'" + item.NIP : (item.NIP || '-');
        var bastNoSafe = item.BAST_NOMOR ? "'" + item.BAST_NOMOR : '-';

        resultData.push([
          noUrut++,                                      // 1: NO
          nibarSafe,                                     // 2: NIBAR
          kodeBarangSafe,                                // 3: KODE BARANG
          item.NAMA_BARANG || '-',                       // 4: NAMA BARANG
          item.MERK_TYPE || '-',                         // 5: SPESIFIKASI NAMA BARANG
          item.LOKASI || '-',                            // 6: LOKASI/ALAMAT PEMAKAI
          item.NAMA_PEMAKAI || '-',                      // 7: NAMA PEMAKAI
          item.STATUS_PEMAKAI || '-',                    // 8: STATUS PEMAKAI
          item.JABATAN || '-',                           // 9: JABATAN
          nikSafe,                                       // 10: NOMOR IDENTITAS PEMAKAI
          item.ALAMAT || '-',                            // 11: ALAMAT
          bastNoSafe,                                    // 12: BAST PEMAKAI NOMOR
          item.BAST_TANGGAL ? Utilities.formatDate(new Date(item.BAST_TANGGAL), Session.getScriptTimeZone(), 'yyyy-MM-dd') : '-', // 13: BAST PEMAKAI TANGGAL
          item.DOK_PEND_NAMA || '-',                     // 14: DOKUMEN PENDUKUNG LAINNYA NAMA
          item.DOK_PEND_TANGGAL ? Utilities.formatDate(new Date(item.DOK_PEND_TANGGAL), Session.getScriptTimeZone(), 'yyyy-MM-dd') : '-', // 15: DOKUMEN PENDUKUNG LAINNYA TANGGAL
          item.KETERANGAN || '-'                         // 16: KETERANGAN
        ]);
      }
    }

    if (resultData.length === 0) {
      return { success: false, message: 'Tidak ada data valid yang dipilih.' };
    }

    var timestamp = Utilities.formatDate(new Date(), Session.getScriptTimeZone(), 'yyyyMMdd_HHmmss');
    var fileName = 'L5_Pinjam_Pakai_' + timestamp;

    var downloadUrl = '';
    var targetSheet = null;

    if (resolvedTemplateId && resolvedTemplateId !== 'TEMPLATE_BARU_KOSONG') {
      // --- PAKAI TEMPLATE ---
      var originalFile = DriveApp.getFileById(resolvedTemplateId);
      var copiedFile;
      if (destFolder) {
        copiedFile = originalFile.makeCopy(fileName, destFolder);
      } else {
        copiedFile = originalFile.makeCopy(fileName);
      }
      copiedFile.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
      var targetSpreadsheet = SpreadsheetApp.openById(copiedFile.getId());
      targetSheet = targetSpreadsheet.getSheets()[0];
      downloadUrl = copiedFile.getUrl();
    } else {
      // --- BUAT SPREADSHEET BARU jika tidak ada template ---
      var newSS;
      if (destFolder) {
        newSS = SpreadsheetApp.create(fileName);
        var newFile = DriveApp.getFileById(newSS.getId());
        destFolder.addFile(newFile);
        DriveApp.getRootFolder().removeFile(newFile);
      } else {
        newSS = SpreadsheetApp.create(fileName);
      }
      DriveApp.getFileById(newSS.getId()).setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
      targetSheet = newSS.getActiveSheet();
      targetSheet.setName('L5 Pinjam Pakai');
      // Header row
      targetSheet.getRange(1, 1, 1, 16).setValues([['NO', 'NIBAR', 'KODE BARANG', 'NAMA BARANG', 'SPESIFIKASI', 'LOKASI', 'NAMA PEMAKAI', 'STATUS', 'JABATAN', 'NIP/NIK', 'ALAMAT', 'BAST NOMOR', 'BAST TANGGAL', 'DOK. PENDUKUNG NAMA', 'DOK. PENDUKUNG TGL', 'KETERANGAN']]);
      downloadUrl = newSS.getUrl();
    }

    // Tulis data mulai baris 12 (jika pakai template) atau baris 2 (jika buat baru)
    var startRow = (resolvedTemplateId && resolvedTemplateId !== 'TEMPLATE_BARU_KOSONG') ? 12 : 2;
    if (resolvedTemplateId && resolvedTemplateId !== 'TEMPLATE_BARU_KOSONG') {
      targetSheet.insertRows(startRow, resultData.length);
    }
    var range = targetSheet.getRange(startRow, 1, resultData.length, 16);
    range.setValues(resultData);

    // Style: Draw border on columns 1-15. No border on column 16 (KETERANGAN).
    var rangeBorders = targetSheet.getRange(startRow, 1, resultData.length, 15);
    rangeBorders.setBorder(true, true, true, true, true, true);
    
    // Clear border on column 16 specifically, in case the template had one by accident or insertRows inherited it
    var rangeKeterangan = targetSheet.getRange(startRow, 16, resultData.length, 1);
    rangeKeterangan.setBorder(false, false, false, false, false, false);
    
    targetSheet.getRange(startRow, 1, resultData.length, 1).setHorizontalAlignment('center');

    logAction(session.username, 'GENERATE_L5', 'Buat Dokumen L5 (' + resultData.length + ' item)');

    return {
      success: true,
      downloadUrl: downloadUrl,
      folderInfo: destFolder ? 'Disimpan di folder: ' + destFolder.getName() : 'Disimpan di Google Drive',
      message: 'Berhasil membuat dokumen L5 (' + resultData.length + ' data).'
    };
  } catch (err) {
    return { success: false, message: 'Gagal membuat dokumen L5: ' + err.message };
  }
}

function generateDocumentPDF(token, payload) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var shPejabat = ss.getSheetByName('Pejabat');
  var shAset = ss.getSheetByName(getSheetNameByType(payload.type));
  var shTmpl = ss.getSheetByName('TemplateDokumen');
  var shDoc = ss.getSheetByName('Dokumen');

  // Load Pejabat
  var mapPejabat = getColumnMap(shPejabat);
  var dataPej = shPejabat.getRange(2, 1, shPejabat.getLastRow() - 1, shPejabat.getLastColumn()).getValues();
  var targetPej = null;
  for (var i = 0; i < dataPej.length; i++) {
    if (dataPej[i][mapPejabat['id'] - 1] === payload.pejabatId) {
      targetPej = dataPej[i];
      break;
    }
  }

  // Jika tidak ada pejabat yang dipilih (karena input UI sudah dihapus), buat array kosong agar aman
  if (!targetPej) {
    targetPej = new Array(shPejabat.getLastColumn()).fill('');
  }

  // Load Template Matching
  var mapTmpl = getColumnMap(shTmpl);
  var dataTmpl = shTmpl.getRange(2, 1, shTmpl.getLastRow() - 1, shTmpl.getLastColumn()).getValues();
  var docNameFull = payload.docTypeCode === 'BA' ? 'Berita Acara' :
    (payload.docTypeCode === 'PI' ? 'Pakta Integritas' :
      (payload.docTypeCode === 'DP' ? 'Daftar Peminjam' :
        (payload.docTypeCode === 'DT' ? 'Daftar Penandatangan' :
          (payload.docTypeCode === 'MDK' ? 'Master Data Kendaraan' :
            (payload.docTypeCode === 'MDP' ? 'Master Data Peralatan' :
              (payload.docTypeCode === 'MDR' ? 'Master Data Rumah Dinas' :
                (payload.docTypeCode === 'BPRD' ? 'BA Pinjam Rumah Dinas' :
              (payload.docTypeCode === 'L5' ? 'L5 Pinjam Pakai Kendaraan Mesin' : 'Dokumen'))))))));
  var activeTemplateContent = '';
  for (var i = 0; i < dataTmpl.length; i++) {
    var row = dataTmpl[i];
    if (String(row[mapTmpl['jenis_aset'] - 1]).toLowerCase().replace(/-/g, ' ') === payload.type.toLowerCase().replace(/-/g, ' ') &&
      row[mapTmpl['jenis_template'] - 1] === docNameFull) {
      activeTemplateContent = row[mapTmpl['isi_template'] - 1];
      break;
    }
  }

  if (!activeTemplateContent) {
    return { success: false, message: 'Template dokumen untuk jenis ' + docNameFull + ' belum diatur.' };
  }

  // Branch for Daftar Peminjam (Excel/Spreadsheet)
  if (docNameFull === 'Daftar Peminjam') {
    return generateExcelDaftarPeminjam(token, activeTemplateContent, payload);
  }

  // Branch for Daftar Penandatangan (Excel/Spreadsheet)
  if (docNameFull === 'Daftar Penandatangan') {
    return generateExcelDaftarPenandatangan(token, activeTemplateContent, payload);
  }

  // Branch for L5 Pinjam Pakai (Excel/Spreadsheet)
  if (docNameFull === 'L5 Pinjam Pakai Kendaraan Mesin') {
    return generateExcelL5PinjamPakai(token, activeTemplateContent, payload);
  }

  // Branch for Master Data (Excel/Spreadsheet)
  if (docNameFull === 'Master Data Kendaraan' || docNameFull === 'Master Data Peralatan' || docNameFull === 'Master Data Rumah Dinas') {
    return generateExcelMasterData(token, activeTemplateContent, payload);
  }

  // Load Assets
  var mapAset = getColumnMap(shAset);
  // UBAH: Gunakan getDisplayValues agar membaca angka 0 di depan sebagai Teks utuh
  var dataAset = shAset.getRange(2, 1, shAset.getLastRow() - 1, shAset.getLastColumn()).getDisplayValues();
  var isDocxMode = !activeTemplateContent.includes('<') && activeTemplateContent.length > 20;

  if (isDocxMode) {
    try {
      var templateFile = DriveApp.getFileById(activeTemplateContent);
      var formattedDate = new Date().toLocaleDateString('id-ID', { year: 'numeric', month: 'long', day: 'numeric' });
      var finalPdfUrls = [];

      // --- LOGIKA FOLDER OTOMATIS ---
      var ssFile = DriveApp.getFileById(ss.getId());
      var parentFolder = ssFile.getParents().next();

      var assetCategoryFolder = getFolderByType(payload.type);
      var rootReportFolderIter = parentFolder.getFoldersByName(assetCategoryFolder);
      var rootReportFolder = rootReportFolderIter.hasNext() ? rootReportFolderIter.next() : parentFolder.createFolder(assetCategoryFolder);

      var specificFolderIter = rootReportFolder.getFoldersByName(docNameFull);
      var specificFolder = specificFolderIter.hasNext() ? specificFolderIter.next() : rootReportFolder.createFolder(docNameFull);

      payload.assetIds.forEach(function (assetId, index) {
        var targetAset = null;
        var targetAsetIndex = -1;
        for (var i = 0; i < dataAset.length; i++) {
          if (dataAset[i][mapAset['id'] - 1] === assetId) { targetAset = dataAset[i]; targetAsetIndex = i; break; }
        }

        if (targetAset) {
          var tempFile = templateFile.makeCopy('TEMP_DOC_' + assetId);
          var tempDoc = DocumentApp.openById(tempFile.getId());
          var body = tempDoc.getBody();

          // --- FIX MARGIN BAWAH OTOMATIS ---
          body.setMarginBottom(20);
          body.replaceText('(?i)\\{\\{NOMOR_DOKUMEN\\}\\}', payload.docNo);
          body.replaceText('(?i)\\{\\{TANGGAL_DOKUMEN\\}\\}', formattedDate);
          
          body.replaceText('(?i)\\{\\{NAMA_PEMINJAM\\}\\}', targetAset[mapAset['NAMA'] - 1] || '');
          body.replaceText('(?i)\\{\\{NIP_PEMINJAM\\}\\}', targetAset[mapAset['NIP'] - 1] || '');
          body.replaceText('(?i)\\{\\{PANGKAT_PEMINJAM\\}\\}', targetAset[mapAset['PANGKAT'] - 1] || targetAset[mapAset['PANGKAT_GOL_RUANG'] - 1] || targetAset[mapAset['PANGKATGOLRUANG'] - 1] || '');
          body.replaceText('(?i)\\{\\{JABATAN_PEMINJAM\\}\\}', targetAset[mapAset['JABATAN'] - 1] || '');
          body.replaceText('(?i)\\{\\{UNIT_KERJA\\}\\}', targetAset[mapAset['UNIT_KERJA'] - 1] || targetAset[mapAset['ORGANISASI_UNIT_KERJA'] - 1] || '');
          body.replaceText('(?i)\\{\\{NAMA_BARANG\\}\\}', targetAset[mapAset['NAMA_BARANG'] - 1] || targetAset[mapAset['JENIS_NAMA_BARANG'] - 1] || targetAset[mapAset['JENIS_BARANGNAMA_BARANG'] - 1] || '');
          body.replaceText('(?i)\\{\\{KODE_BARANG\\}\\}', targetAset[mapAset['KODE_BARANG'] - 1] || '');
          body.replaceText('(?i)\\{\\{NIBAR\\}\\}', targetAset[mapAset['NIBAR'] - 1] || targetAset[mapAset['NOMOR_REGISTER'] - 1] || '');
          body.replaceText('(?i)\\{\\{MEREK\\}\\}', targetAset[mapAset['MERK_TYPE'] - 1] || '');
          body.replaceText('(?i)\\{\\{MERK_TYPE\\}\\}', targetAset[mapAset['MERK_TYPE'] - 1] || '');
          body.replaceText('(?i)\\{\\{UKURAN\\}\\}', targetAset[mapAset['UKURAN_CC'] - 1] || '');
          body.replaceText('(?i)\\{\\{BAHAN\\}\\}', targetAset[mapAset['BAHAN'] - 1] || '');
          body.replaceText('(?i)\\{\\{TAHUN_PEROLEHAN\\}\\}', String(targetAset[mapAset['TAHUN'] - 1] || targetAset[mapAset['TAHUN_PEROLEHAN'] - 1] || ''));
          body.replaceText('(?i)\\{\\{TAHUN\\}\\}', String(targetAset[mapAset['TAHUN'] - 1] || targetAset[mapAset['TAHUN_PEROLEHAN'] - 1] || ''));
          body.replaceText('(?i)\\{\\{NOMOR_RANGKA\\}\\}', targetAset[mapAset['NO_RANGKA'] - 1] || targetAset[mapAset['NO_RANGKA_SN'] - 1] || '');
          body.replaceText('(?i)\\{\\{NOMOR_MESIN\\}\\}', targetAset[mapAset['NO_MESIN'] - 1] || '');
          body.replaceText('(?i)\\{\\{NOMOR_POLISI\\}\\}', targetAset[mapAset['NO_POLISI'] - 1] || '');
          body.replaceText('(?i)\\{\\{NOMOR_BPKB\\}\\}', targetAset[mapAset['NO_BPKB'] - 1] || '');
          body.replaceText('(?i)\\{\\{NO_POLISI_RANGKA\\}\\}', payload.type === 'kendaraan' ? (targetAset[mapAset['NO_POLISI'] - 1] || '-') : (targetAset[mapAset['NOMOR_REGISTER'] - 1] || '-'));
          
          // TAG KHUSUS RUMAH DINAS
          body.replaceText('(?i)\\{\\{KONDISI\\}\\}', targetAset[mapAset['KONDISI_BANGUNAN_BKBRB'] - 1] || '');
          body.replaceText('(?i)\\{\\{KONSTRUKSI\\}\\}', targetAset[mapAset['KONTRUKSI_BANGUNAN'] - 1] || '');
          body.replaceText('(?i)\\{\\{ALAMAT\\}\\}', targetAset[mapAset['LETAKLOKASI_ALAMAT'] - 1] || '');
          body.replaceText('(?i)\\{\\{LETAK_LOKASI\\}\\}', targetAset[mapAset['LETAKLOKASI_ALAMAT'] - 1] || '');
          body.replaceText('(?i)\\{\\{LUAS_LANTAI\\}\\}', String(targetAset[mapAset['LUAS_LANTAI'] - 1] || ''));
          body.replaceText('(?i)\\{\\{LUAS\\}\\}', String(targetAset[mapAset['LUAS'] - 1] || ''));
          body.replaceText('(?i)\\{\\{DOKUMEN_GEDUNG\\}\\}', targetAset[mapAset['DOKUMEN_GEDUNG'] - 1] || '');
          body.replaceText('(?i)\\{\\{STATUS_TANAH\\}\\}', targetAset[mapAset['STATUS_TANAH'] - 1] || '');
          body.replaceText('(?i)\\{\\{PENGGUNAAN\\}\\}', targetAset[mapAset['PENGGUNAAN'] - 1] || '');
          body.replaceText('(?i)\\{\\{ASAL_USUL\\}\\}', targetAset[mapAset['ASAL_USUL'] - 1] || '');
          body.replaceText('(?i)\\{\\{NOMER_SERTIFIKAT\\}\\}', targetAset[mapAset['NOMER_SERTIFIKAT'] - 1] || '');

          body.replaceText('(?i)\\{\\{NAMA_PEJABAT\\}\\}', targetPej[mapPejabat['nama_pejabat'] - 1] || '');
          body.replaceText('(?i)\\{\\{NIP_PEJABAT\\}\\}', targetPej[mapPejabat['nip'] - 1] || '');
          body.replaceText('(?i)\\{\\{JABATAN_PEJABAT\\}\\}', targetPej[mapPejabat['jabatan'] - 1] || '');

          var arrTags = [
            { tag: '(?i)\\{\\{foto_kendaraan\\}\\}', url: targetAset[mapAset['FOTO_KENDARAAN'] - 1] || '', type: 'kendaraan' },
            { tag: '(?i)\\{\\{foto_stnk\\}\\}', url: targetAset[mapAset['FOTO_STNK'] - 1] || '', type: 'stnk' },
            { tag: '(?i)\\{\\{foto_pajak\\}\\}', url: targetAset[mapAset['FOTO_PAJAK'] - 1] || '', type: 'pajak' },
            { tag: '(?i)\\{\\{foto_peralatan\\}\\}', url: targetAset[mapAset['FOTO_BARANG'] - 1] || '', type: 'peralatan' },
            { tag: '(?i)\\{\\{foto_rumah_dinas\\}\\}', url: targetAset[mapAset['FOTO_RUMAH_DINAS'] - 1] || '', type: 'rumah-dinas' }
          ];

          arrTags.forEach(function (itemTag) {
            var element = body.findText(itemTag.tag);
            if (element) {
              var textObj = element.getElement().asText();
              var actualUrl = itemTag.url;
              if (actualUrl && typeof actualUrl === 'string' && actualUrl.trim().startsWith('[')) {
                try {
                  var arrUrl = JSON.parse(actualUrl);
                  if (arrUrl && arrUrl.length > 0) {
                    actualUrl = arrUrl[arrUrl.length - 1].url;
                  }
                } catch (e) {
                  // Abaikan
                }
              }

              if (actualUrl && actualUrl.indexOf('drive.google.com') !== -1) {
                try {
                  var fileIdMatch = actualUrl.match(/[-\w]{25,}/);
                  if (fileIdMatch && fileIdMatch[0]) {
                    var imgBlob = DriveApp.getFileById(fileIdMatch[0]).getBlob();
                    var parent = textObj.getParent();
                    if (parent.getType() === DocumentApp.ElementType.PARAGRAPH) {
                      var img = parent.asParagraph().insertInlineImage(element.getStartOffset(), imgBlob);

                      // SCALE PROPORTIONALLY TO MAINTAIN ASPECT RATIO
                      var origW = img.getWidth();
                      var origH = img.getHeight();
                      if (origW > 0 && origH > 0) {
                        if (itemTag.type === 'kendaraan' || itemTag.type === 'peralatan' || itemTag.type === 'mesin' || itemTag.type === 'penghapusan-kendaraan' || itemTag.type === 'penghapusan-mesin' || itemTag.type === 'alkes' || itemTag.type === 'penghapusan-alkes') {
                          var maxW = 263;
                          var maxH = 370;
                          var ratio = Math.min(maxW / origW, maxH / origH);
                          img.setWidth(Math.round(origW * ratio));
                          img.setHeight(Math.round(origH * ratio));
                        } else if (itemTag.type === 'rumah-dinas') {
                          var targetW = 550; // Enlarge image
                          var ratio = targetW / origW;
                          img.setWidth(targetW);
                          img.setHeight(Math.round(origH * ratio));
                        } else if (itemTag.type === 'stnk' || itemTag.type === 'pajak') {
                          var maxW = 428; // ~ 15.11 cm
                          var maxH = 285; // ~ 10.08 cm
                          var ratio = Math.min(maxW / origW, maxH / origH);
                          img.setWidth(Math.round(origW * ratio));
                          img.setHeight(Math.round(origH * ratio));
                        }
                      } else {
                        if (itemTag.type === 'kendaraan' || itemTag.type === 'peralatan' || itemTag.type === 'mesin' || itemTag.type === 'penghapusan-kendaraan' || itemTag.type === 'penghapusan-mesin' || itemTag.type === 'alkes' || itemTag.type === 'penghapusan-alkes') {
                          img.setWidth(263);
                          img.setHeight(370);
                        } else if (itemTag.type === 'rumah-dinas') {
                          img.setWidth(550);
                          img.setHeight(350); // Fallback height
                        } else if (itemTag.type === 'stnk' || itemTag.type === 'pajak') {
                          img.setWidth(428);
                          img.setHeight(263);
                        }
                      }
                    }
                  }
                } catch (e) {
                  // Abaikan jika gambar gagal ditarik
                }
              }
              textObj.replaceText(itemTag.tag, ''); // Hapus teks tag kurung kurawalnya
            }
          });
          // ---------------------------------------------------------------

          tempDoc.saveAndClose();

          var pdfBlob = tempFile.getAs('application/pdf');
          var namaPeminjamText = targetAset[mapAset['NAMA'] - 1] || assetId;
          var seqNum = payload.fileIndex || (index + 1);
          var matchId = String(assetId).match(/\d+$/);
          if (matchId) {
            seqNum = parseInt(matchId[0], 10);
          }
          var tglStr = Utilities.formatDate(new Date(), Session.getScriptTimeZone(), "yyyy-MM-dd");
          var namaFileBaru = seqNum + '. Dokumen_' + docNameFull + '_' + namaPeminjamText + '_' + tglStr + '.pdf';
          pdfBlob.setName(namaFileBaru);

          // --- FITUR BARU: Hapus File Lama Agar Tidak Double (Timpa File) ---
          var existingFiles = specificFolder.getFilesByName(namaFileBaru);
          while (existingFiles.hasNext()) {
            existingFiles.next().setTrashed(true);
          }
          // ------------------------------------------------------------------

          var finalPdf = specificFolder.createFile(pdfBlob);
          finalPdf.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);

          finalPdfUrls.push({ id: assetId, url: finalPdf.getUrl() });
          tempFile.setTrashed(true);

          var newDocId = 'DOC-' + Utilities.getUuid().split('-')[0];
          shDoc.appendRow([
            newDocId, payload.type, assetId, docNameFull, payload.docNo, new Date().toISOString().substring(0, 10),
            targetAset[mapAset['NAMA'] - 1], targetAset[mapAset['NIP'] - 1],
            targetAset[mapAset['UNIT_KERJA'] - 1] || targetAset[mapAset['ORGANISASI_UNIT_KERJA'] - 1] || '',
            targetPej[mapPejabat['nama_pejabat'] - 1], payload.action === 'print' ? 'Printed' : 'PDF Saved',
            finalPdf.getUrl(), session.username, new Date().toISOString()
          ]);

          // Update LINK_BA, LINK_PI, dsb di sheet utama
          var targetColName = '';
          if (payload.docTypeCode === 'BA' || payload.docTypeCode === 'BPRD') targetColName = 'LINK_BA';
          else if (payload.docTypeCode === 'PI') targetColName = 'LINK_PI';
          else if (payload.docTypeCode === 'DP') targetColName = 'LINK_DP';
          else if (payload.docTypeCode === 'DT') targetColName = 'LINK_DT';
          else if (payload.docTypeCode === 'MDK' || payload.docTypeCode === 'MDP' || payload.docTypeCode === 'MDR') targetColName = 'LINK_MD';

          if (targetColName && mapAset[targetColName] && targetAsetIndex > -1) {
            shAset.getRange(targetAsetIndex + 2, mapAset[targetColName]).setValue(finalPdf.getUrl());
          }
        }
      });
      return {
        success: true,
        isDocxMode: true,
        pdfUrl: finalPdfUrls.length > 0 ? finalPdfUrls[0].url : '',
        pdfUrls: finalPdfUrls
      };
    } catch (err) {
      return { success: false, message: 'Gagal memproses template DOCX: ' + err.message };
    }
  }

  // --- LOGIKA HTML LAMA ---
  var combinedHTML = '';
  var count = 0;

  payload.assetIds.forEach(function (assetId) {
    var targetAset = null;
    for (var i = 0; i < dataAset.length; i++) {
      if (dataAset[i][mapAset['id'] - 1] === assetId) {
        targetAset = dataAset[i];
        break;
      }
    }

    if (targetAset) {
      var formattedDate = new Date().toLocaleDateString('id-ID', { year: 'numeric', month: 'long', day: 'numeric' });

      var replaced = activeTemplateContent
        .replace(/\{\{NOMOR_DOKUMEN\}\}/gi, payload.docNo)
        .replace(/\{\{TANGGAL_DOKUMEN\}\}/gi, formattedDate)
        .replace(/\{\{NAMA_PEMINJAM\}\}/gi, targetAset[mapAset['NAMA'] - 1] || '')
        .replace(/\{\{NIP_PEMINJAM\}\}/gi, targetAset[mapAset['NIP'] - 1] || '')
        .replace(/\{\{PANGKAT_PEMINJAM\}\}/gi, targetAset[mapAset['PANGKAT'] - 1] || targetAset[mapAset['PANGKAT_GOL_RUANG'] - 1] || '')
        .replace(/\{\{JABATAN_PEMINJAM\}\}/gi, targetAset[mapAset['JABATAN'] - 1] || '')
        .replace(/\{\{UNIT_KERJA\}\}/gi, targetAset[mapAset['UNIT_KERJA'] - 1] || targetAset[mapAset['ORGANISASI_UNIT_KERJA'] - 1] || '')
        .replace(/\{\{NAMA_BARANG\}\}/gi, targetAset[mapAset['NAMA_BARANG'] - 1] || targetAset[mapAset['JENIS_NAMA_BARANG'] - 1] || '')
        .replace(/\{\{KODE_BARANG\}\}/gi, targetAset[mapAset['KODE_BARANG'] - 1] || '')
        .replace(/\{\{NIBAR\}\}/gi, targetAset[mapAset['NIBAR'] - 1] || targetAset[mapAset['NOMOR_REGISTER'] - 1] || '')
        .replace(/\{\{MEREK\}\}/gi, targetAset[mapAset['MERK_TYPE'] - 1] || '')
        .replace(/\{\{MERK_TYPE\}\}/gi, targetAset[mapAset['MERK_TYPE'] - 1] || '')
        .replace(/\{\{UKURAN\}\}/gi, targetAset[mapAset['UKURAN_CC'] - 1] || '')
        .replace(/\{\{BAHAN\}\}/gi, targetAset[mapAset['BAHAN'] - 1] || '')
        .replace(/\{\{TAHUN_PEROLEHAN\}\}/gi, String(targetAset[mapAset['TAHUN'] - 1] || targetAset[mapAset['TAHUN_PEROLEHAN'] - 1] || ''))
        .replace(/\{\{TAHUN\}\}/gi, String(targetAset[mapAset['TAHUN'] - 1] || targetAset[mapAset['TAHUN_PEROLEHAN'] - 1] || ''))
        .replace(/\{\{NOMOR_RANGKA\}\}/gi, targetAset[mapAset['NO_RANGKA'] - 1] || targetAset[mapAset['NO_RANGKA_SN'] - 1] || '')
        .replace(/\{\{NOMOR_MESIN\}\}/gi, targetAset[mapAset['NO_MESIN'] - 1] || '')
        .replace(/\{\{NOMOR_POLISI\}\}/gi, targetAset[mapAset['NO_POLISI'] - 1] || '')
        .replace(/\{\{NOMOR_BPKB\}\}/gi, targetAset[mapAset['NO_BPKB'] - 1] || '')
        .replace(/\{\{NO_POLISI_RANGKA\}\}/gi, payload.type === 'kendaraan' ? (targetAset[mapAset['NO_POLISI'] - 1] || '-') : (targetAset[mapAset['NOMOR_REGISTER'] - 1] || '-'))
        .replace(/\{\{NAMA_PEJABAT\}\}/gi, targetPej[mapPejabat['nama_pejabat'] - 1] || '')
        .replace(/\{\{NIP_PEJABAT\}\}/gi, targetPej[mapPejabat['nip'] - 1] || '')
        .replace(/\{\{JABATAN_PEJABAT\}\}/gi, targetPej[mapPejabat['jabatan'] - 1] || '');

      combinedHTML += `<div class="print-page-wrapper" style="${count > 0 ? 'page-break-before: always; margin-top: 40px;' : ''}">${replaced}</div>`;

      var newDocId = 'DOC-' + Utilities.getUuid().split('-')[0];
      shDoc.appendRow([
        newDocId, payload.type, assetId, docNameFull, payload.docNo, new Date().toISOString().substring(0, 10),
        targetAset[mapAset['NAMA'] - 1], targetAset[mapAset['NIP'] - 1],
        targetAset[mapAset['UNIT_KERJA'] - 1] || targetAset[mapAset['ORGANISASI_UNIT_KERJA'] - 1] || '',
        targetPej[mapPejabat['nama_pejabat'] - 1], payload.action === 'print' ? 'Printed' : 'PDF Saved',
        '', session.username, new Date().toISOString()
      ]);
      count++;
    }
  });

  if (payload.action === 'print') {
    return { success: true, isDocxMode: false, htmlContent: combinedHTML };
  } else {
    try {
      var htmlFullBlob = `
        <html><head><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{font-family:'Times New Roman',Times,serif;font-size:11pt;line-height:1.4;padding:20px;}.kop-surat{text-align:center;border-bottom:4px double #000;padding-bottom:12px;margin-bottom:25px;}.kop-surat h4{margin:2px 0;font-size:14pt;font-weight:bold;}.kop-surat h5{margin:2px 0;font-size:11pt;font-weight:bold;}.placeholder-field{border-bottom:1px dashed #000;padding:0 4px;font-weight:bold;}.print-page-wrapper{page-break-after:always;}</style></head><body>${combinedHTML}</body></html>
      `;
      var htmlOutput = HtmlService.createHtmlOutput(htmlFullBlob);
      var pdfBlob = htmlOutput.getAs('application/pdf').setName('Dokumen_Aset_SIMAS_' + payload.docNo.replace(/\//g, '_') + '.pdf');

      var file = DriveApp.createFile(pdfBlob);
      file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);

      return { success: true, isDocxMode: false, pdfUrl: file.getUrl() };
    } catch (e) {
      return { success: false, message: 'PDF Error: ' + e.message };
    }
  }
}

// API: User Management Services
function getUsers(token) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getSheetByName('Users');
  var data = sheet.getDataRange().getValues();
  var headers = data[0];
  var permIdx = headers.indexOf('permissions');

  var list = [];
  for (var i = 1; i < data.length; i++) {
    list.push({
      username: data[i][0],
      fullname: data[i][2],
      role: data[i][3],
      status: data[i][4] || 'Aktif',
      permissions: permIdx > -1 && data[i][permIdx] ? String(data[i][permIdx]) : ''
    });
  }

  return { success: true, data: list };
}

function createUser(token, payload) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getSheetByName('Users');

  // Check Username exists
  var data = sheet.getDataRange().getValues();
  for (var i = 1; i < data.length; i++) {
    if (String(data[i][0]).toLowerCase() === payload.username.toLowerCase()) {
      return { success: false, message: 'Username sudah terdaftar.' };
    }
  }

  sheet.appendRow([
    payload.username,
    hashPassword(payload.password),
    payload.fullname,
    payload.role,
    payload.status
  ]);

  logAction(session.username, 'CREATE_USER', 'Membuat user baru: ' + payload.username);
  return { success: true };
}

function changeUserPassword(token, targetUsername, newPassword) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  if (!newPassword || newPassword.length < 6) {
    return { success: false, message: 'Password minimal 6 karakter.' };
  }

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getSheetByName('Users');
  var data = sheet.getDataRange().getValues();

  for (var i = 1; i < data.length; i++) {
    if (data[i][0] === targetUsername) {
      sheet.getRange(i + 1, 2).setValue(hashPassword(newPassword));
      logAction(session.username, 'CHANGE_PASSWORD', 'Ganti password user: ' + targetUsername);
      return { success: true };
    }
  }
  return { success: false, message: 'User tidak ditemukan.' };
}

// Ganti password milik sendiri — wajib verifikasi password lama
function changeSelfPassword(token, currentPassword, newPassword) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  if (!newPassword || newPassword.length < 8) {
    return { success: false, message: 'Password baru minimal 8 karakter.' };
  }

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getSheetByName('Users');
  var data = sheet.getDataRange().getValues();
  var hashedCurrent = hashPassword(currentPassword);

  for (var i = 1; i < data.length; i++) {
    if (data[i][0] === session.username) {
      if (data[i][1] !== hashedCurrent) {
        return { success: false, message: 'Password saat ini tidak sesuai.' };
      }
      sheet.getRange(i + 1, 2).setValue(hashPassword(newPassword));
      logAction(session.username, 'CHANGE_SELF_PASSWORD', 'User mengganti password sendiri.');
      return { success: true };
    }
  }
  return { success: false, message: 'User tidak ditemukan.' };
}

function deleteUser(token, targetUsername) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getSheetByName('Users');
  var data = sheet.getDataRange().getValues();

  for (var i = 1; i < data.length; i++) {
    if (data[i][0] === targetUsername) {
      // Proteksi: role Admin tidak boleh dihapus
      if (data[i][3] === 'Admin') {
        return { success: false, message: 'User dengan role Admin tidak dapat dihapus.' };
      }
      sheet.deleteRow(i + 1);
      logAction(session.username, 'DELETE_USER', 'Menghapus user: ' + targetUsername);
      return { success: true };
    }
  }
  return { success: false, message: 'User tidak ditemukan.' };
}
