// Helper untuk mempermudah pencarian dan pembuatan folder
function getOrCreateFolder(parent, name) {
  var folders = parent.getFoldersByName(name);
  if (folders.hasNext()) {
    return folders.next();
  }
  return parent.createFolder(name);
}

// Helper untuk menambahkan foto baru ke dalam riwayat JSON
function appendToHistory(oldValue, newUrl, dateStr) {
  var history = [];
  if (oldValue) {
    if (typeof oldValue === 'string' && oldValue.trim().startsWith('[')) {
      try {
        history = JSON.parse(oldValue);
      } catch (e) {
        history = [{ url: oldValue, date: "Old Record" }];
      }
    } else if (typeof oldValue === 'string' && oldValue.trim() !== '') {
      history = [{ url: oldValue, date: "Old Record" }];
    }
  }
  history.push({ url: newUrl, date: dateStr });
  return JSON.stringify(history);
}

function saveLampiranToDrive(token, assetId, stnkObj, pajakObj, kendaraanObj) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var ssFile = DriveApp.getFileById(ss.getId());

    // 1. Dapatkan folder tempat Spreadsheet ini berada
    var parentFolder = ssFile.getParents().next();

    // 2. Ambil nama pemegang dari database
    var sheet = ss.getSheetByName('Kendaraan');
    var data = sheet.getDataRange().getValues();
    var headers = data[0];
    var idIdx = headers.indexOf('id');
    var namaIdx = headers.indexOf('NAMA');
    var stnkIdx = headers.indexOf('FOTO_STNK');
    var pajakIdx = headers.indexOf('FOTO_PAJAK');
    var kendaraanIdx = headers.indexOf('FOTO_KENDARAAN');

    var namaPemegang = "Unknown";
    var rowToUpdate = -1;
    var oldStnkVal = "";
    var oldPajakVal = "";
    var oldKendaraanVal = "";

    for (var i = 1; i < data.length; i++) {
      if (data[i][idIdx] === assetId) {
        namaPemegang = data[i][namaIdx] ? data[i][namaIdx].toString().trim() : "Unknown";
        rowToUpdate = i + 1;
        oldStnkVal = data[i][stnkIdx] || "";
        oldPajakVal = data[i][pajakIdx] || "";
        oldKendaraanVal = kendaraanIdx > -1 ? (data[i][kendaraanIdx] || "") : "";
        break;
      }
    }

    if (rowToUpdate === -1) {
      return { success: false, message: 'Data kendaraan tidak ditemukan.' };
    }

    // 3. Buat Hirarki Folder
    var lampiranFotoFolder = getOrCreateFolder(parentFolder, "Lampiran foto");
    var kendaraanFolder = getOrCreateFolder(lampiranFotoFolder, "Lampiran_foto_kendaraan");

    var dateString = Utilities.formatDate(new Date(), "Asia/Jakarta", "dd-MM-yyyy");

    var stnkUrl = null;
    var pajakUrl = null;
    var kendaraanUrl = null;

    // Fungsi Helper Upload
    function processUpload(fileObj, prefix, targetFolder) {
      if (!fileObj || !fileObj.base64) return null;
      var dataStr = fileObj.base64.split(',')[1];

      // Ambil ekstensi dari mimeType jika memungkinkan
      var ext = "";
      if (fileObj.mimeType) {
        if (fileObj.mimeType.indexOf("image/png") !== -1) ext = ".png";
        else if (fileObj.mimeType.indexOf("image/jpeg") !== -1) ext = ".jpg";
        else if (fileObj.mimeType.indexOf("application/pdf") !== -1) ext = ".pdf";
      }

      // Format nama: foto_stnk_Budi_12-06-2026.png
      var fileName = prefix + "_" + namaPemegang + "_" + dateString + ext;
      var blob = Utilities.newBlob(Utilities.base64Decode(dataStr), fileObj.mimeType, fileName);
      var file = targetFolder.createFile(blob);
      file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
      return file.getUrl();
    }

    // 4. Proses Upload ke masing-masing subfolder
    if (stnkObj) {
      var folderStnk = getOrCreateFolder(kendaraanFolder, "foto_stnk");
      stnkUrl = processUpload(stnkObj, "foto_stnk", folderStnk);
    }
    if (pajakObj) {
      var folderPajak = getOrCreateFolder(kendaraanFolder, "foto_pajak");
      pajakUrl = processUpload(pajakObj, "foto_pajak", folderPajak);
    }
    if (kendaraanObj) {
      var folderKendaraan = getOrCreateFolder(kendaraanFolder, "foto_kendaraan");
      kendaraanUrl = processUpload(kendaraanObj, "foto_kendaraan", folderKendaraan);
    }

    // 5. Update Database dengan format Riwayat (Array JSON)
    if (stnkUrl) {
      sheet.getRange(rowToUpdate, stnkIdx + 1).setValue(appendToHistory(oldStnkVal, stnkUrl, dateString));
    }
    if (pajakUrl) {
      sheet.getRange(rowToUpdate, pajakIdx + 1).setValue(appendToHistory(oldPajakVal, pajakUrl, dateString));
    }
    if (kendaraanUrl && kendaraanIdx > -1) {
      sheet.getRange(rowToUpdate, kendaraanIdx + 1).setValue(appendToHistory(oldKendaraanVal, kendaraanUrl, dateString));
    }

    logAction(session.username, 'UPDATE_LAMPIRAN', 'Update file lampiran untuk aset kendaraan: ' + assetId);

    // Paksa Spreadsheet untuk menyimpan perubahan sebelum me-return response ke client
    SpreadsheetApp.flush();

    return {
      success: true,
      stnkUrl: stnkUrl,
      pajakUrl: pajakUrl,
      kendaraanUrl: kendaraanUrl,
      message: 'Lampiran kendaraan berhasil disimpan dan diunggah ke Google Drive.'
    };

  } catch (e) {
    return { success: false, message: 'Gagal mengunggah file: ' + e.message };
  }
}

