// = powered gas by agunk
// ==========================================
function getPengaturanData(token) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheet = ss.getSheetByName("Pengaturan");

    if (!sheet) {
      sheet = ss.insertSheet("Pengaturan");
      sheet.appendRow(["kunci", "nilai"]);
    }

    var keys = [
      "TEMPLATE_KENDARAAN_BESAR", "TEMPLATE_KENDARAAN_SEDANG", "TEMPLATE_KENDARAAN_MENENGAH", "TEMPLATE_KENDARAAN_KECIL",
      "TEMPLATE_PERALATAN_BESAR", "TEMPLATE_PERALATAN_SEDANG", "TEMPLATE_PERALATAN_MENENGAH", "TEMPLATE_PERALATAN_KECIL",
      "TEMPLATE_MESIN_BESAR", "TEMPLATE_MESIN_SEDANG", "TEMPLATE_MESIN_MENENGAH", "TEMPLATE_MESIN_KECIL",
      "TEMPLATE_RUANGAN_BESAR", "TEMPLATE_RUANGAN_SEDANG", "TEMPLATE_RUANGAN_MENENGAH", "TEMPLATE_RUANGAN_KECIL"
    ];

    var dataArr = sheet.getDataRange().getValues();
    var existingKeys = [];
    for (var i = 1; i < dataArr.length; i++) {
      existingKeys.push(dataArr[i][0]);
    }

    // Tambahkan kunci yang belum ada ke database
    keys.forEach(function (k) {
      if (existingKeys.indexOf(k) === -1) {
        sheet.appendRow([k, ""]);
      }
    });

    var finalData = sheet.getDataRange().getValues();
    var obj = {};
    for (var j = 1; j < finalData.length; j++) {
      if (finalData[j][0]) obj[finalData[j][0]] = finalData[j][1];
    }
    return { success: true, data: obj };
  } catch (err) {
    return { success: false, message: "Gagal mengambil pengaturan: " + err.message };
  }
}
