// ==========================================
// = FITUR BARU: AUTO SCAN TAGS WORKSPACE
// ==========================================
function autoScanTags(token, id) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message };

  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheet = ss.getSheetByName('TemplateDokumen');
    var data = sheet.getDataRange().getValues();
    var map = getColumnMap(sheet);
    var docId = '';

    for (var i = 0; i < data.length; i++) {
      // PERBAIKAN: Tambah -1 agar array membaca kolom yang tepat
      if (data[i][map['id'] - 1] === id) {
        docId = data[i][map['isi_template'] - 1];
        break;
      }
    }

    if (!docId || docId.length < 33 || docId.includes('<')) {
      return { success: false, message: 'Template ini masih menggunakan format HTML lama. Silakan "Upload Master" file .DOCX terlebih dahulu sebelum menggunakan Workspace.' };
    }

    var doc = DocumentApp.openById(docId);
    var text = doc.getBody().getText();
    // Scan tag {{nama_tag}}
    var tags = text.match(/\{\{[a-zA-Z0-9_]+\}\}/gi) || [];
    var uniqueTags = [...new Set(tags)];

    // Cek keamanan jika kolom tags terhapus tidak sengaja
    if (!map['tags']) {
      sheet.getRange(1, sheet.getLastColumn() + 1).setValue('tags');
      map = getColumnMap(sheet);
    }

    // Simpan kembali tag yang terbaru ke database
    for (var j = 0; j < data.length; j++) {
      if (data[j][map['id'] - 1] === id) {
        sheet.getRange(j + 1, map['tags']).setValue(JSON.stringify(uniqueTags));
        break;
      }
    }

    return { success: true, tags: uniqueTags };
  } catch (e) {
    return { success: false, message: e.toString() };
  }
}
// ==========================================
// = FITUR BARU: TAMBAH MASTER TEMPLATE BARU
// = powered gas by agunk & code puzzle
// ==========================================
function addNewTemplate(token, jenisAset, jenisTemplate, namaTemplate, formatFile) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheet = ss.getSheetByName('TemplateDokumen');
    if (!sheet) return { success: false, message: 'Tabel TemplateDokumen tidak ditemukan.' };

    var map = getColumnMap(sheet);
    var data = sheet.getDataRange().getValues();

    // Auto-tambah kolom tags jika belum ada di server
    if (map['tags'] === undefined) {
      sheet.getRange(1, sheet.getLastColumn() + 1).setValue('tags');
      map = getColumnMap(sheet);
    }

    // Generate ID baru otomatis (T-00X)
    var maxSeq = 0;
    for (var i = 1; i < data.length; i++) {
      var currId = String(data[i][map['id'] - 1] || '');
      if (currId.startsWith('T-')) {
        var seq = parseInt(currId.replace('T-', ''), 10);
        if (!isNaN(seq) && seq > maxSeq) {
          maxSeq = seq;
        }
      }
    }
    var nextSeq = maxSeq + 1;
    var newId = 'T-' + ('000' + nextSeq).slice(-3);

    // Siapkan array baris baru
    var newRow = new Array(sheet.getLastColumn()).fill('');
    newRow[map['id'] - 1] = newId;
    newRow[map['jenis_aset'] - 1] = jenisAset;
    newRow[map['jenis_template'] - 1] = jenisTemplate; // Diisi sesuai pilihan pengguna di form
    newRow[map['nama_template'] - 1] = namaTemplate;
    newRow[map['isi_template'] - 1] = 'TEMPLATE_BARU_KOSONG';
    newRow[map['status'] - 1] = 'Aktif';
    newRow[map['created_at'] - 1] = new Date().toISOString();
    newRow[map['tags'] - 1] = formatFile === 'Excel' ? '["Template Excel / Spreadsheet"]' : '[]';

    // Simpan ke database
    sheet.appendRow(newRow);
    logAction(session.username, 'ADD_TEMPLATE', 'Menambahkan master dokumen baru: ' + namaTemplate);

    return { success: true };
  } catch (e) {
    return { success: false, message: e.message };
  }
}
// ==========================================
// = FITUR BARU: GENERATE ZIP BATCH (WA, EMAIL, DOWNLOAD)
// = powered gas by agunk & code puzzle
// ==========================================
function generateZipDocument(token, payload) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var shPejabat = ss.getSheetByName('Pejabat');
  var shAset = ss.getSheetByName(getSheetNameByType(payload.type));
  var shTmpl = ss.getSheetByName('TemplateDokumen');
  var shDoc = ss.getSheetByName('Dokumen');

  // Load Template Matching
  var mapTmpl = getColumnMap(shTmpl);
  var dataTmpl = shTmpl.getRange(2, 1, shTmpl.getLastRow() - 1, shTmpl.getLastColumn()).getValues();
  var activeTemplateContent = '';
  var docNameFull = payload.docTypeCode === 'BA' ? 'Berita Acara' :
    (payload.docTypeCode === 'PI' ? 'Pakta Integritas' :
      (payload.docTypeCode === 'DP' ? 'Daftar Peminjam' :
        (payload.docTypeCode === 'DT' ? 'Daftar Penandatangan' :
          (payload.docTypeCode === 'MDK' ? 'Master Data Kendaraan' :
            (payload.docTypeCode === 'MDP' ? 'Master Data Peralatan' :
              (payload.docTypeCode === 'MDR' ? 'Master Data Rumah Dinas' :
                (payload.docTypeCode === 'BPRD' ? 'BA Pinjam Rumah Dinas' :
              (payload.docTypeCode === 'L5' ? 'L5 Pinjam Pakai Kendaraan Mesin' : 'Dokumen'))))))));

  for (var i = 0; i < dataTmpl.length; i++) {
    var row = dataTmpl[i];
    if (String(row[mapTmpl['jenis_aset'] - 1]).toLowerCase() === payload.type.toLowerCase() &&
      row[mapTmpl['jenis_template'] - 1] === docNameFull) {
      activeTemplateContent = row[mapTmpl['isi_template'] - 1];
      break;
    }
  }

  if (!activeTemplateContent) {
    return { success: false, message: 'Template dokumen untuk jenis ' + docNameFull + ' belum diatur.' };
  }

  // Load Assets & Pejabat
  var mapAset = getColumnMap(shAset);
  // UBAH: Gunakan getDisplayValues agar membaca angka 0 di depan sebagai Teks utuh
  var dataAset = shAset.getRange(2, 1, shAset.getLastRow() - 1, shAset.getLastColumn()).getDisplayValues();
  var mapPejabat = getColumnMap(shPejabat);

  // Karena fitur pilih pejabat dihapus (manual dari template), siapkan data array kosong agar kebal error
  var targetPej = new Array(shPejabat.getLastColumn()).fill('');

  var isDocxMode = !activeTemplateContent.includes('<') && activeTemplateContent.length > 20;
  var pdfBlobs = [];
  var formattedDate = new Date().toLocaleDateString('id-ID', { year: 'numeric', month: 'long', day: 'numeric' });

  if (isDocxMode) {
    try {
      var templateFile = DriveApp.getFileById(activeTemplateContent);

      payload.assetIds.forEach(function (assetId, index) {
        var targetAset = null;
        for (var i = 0; i < dataAset.length; i++) {
          if (dataAset[i][mapAset['id'] - 1] === assetId) { targetAset = dataAset[i]; break; }
        }

        if (targetAset) {
          var tempFile = templateFile.makeCopy('TEMP_DOC_' + assetId);
          var tempDoc = DocumentApp.openById(tempFile.getId());
          var body = tempDoc.getBody();

          body.setMarginBottom(20);

          body.replaceText('(?i)\\{\\{NOMOR_DOKUMEN\\}\\}', "");
          body.replaceText('(?i)\\{\\{TANGGAL_DOKUMEN\\}\\}', formattedDate);
          body.replaceText('(?i)\\{\\{NAMA_PEMINJAM\\}\\}', targetAset[mapAset['NAMA'] - 1] || '');
          body.replaceText('(?i)\\{\\{NIP_PEMINJAM\\}\\}', targetAset[mapAset['NIP'] - 1] || '');
          body.replaceText('(?i)\\{\\{PANGKAT_PEMINJAM\\}\\}', targetAset[mapAset['PANGKAT'] - 1] || targetAset[mapAset['PANGKAT_GOL_RUANG'] - 1] || '');
          body.replaceText('(?i)\\{\\{JABATAN_PEMINJAM\\}\\}', targetAset[mapAset['JABATAN'] - 1] || '');
          body.replaceText('(?i)\\{\\{UNIT_KERJA\\}\\}', targetAset[mapAset['UNIT_KERJA'] - 1] || targetAset[mapAset['ORGANISASI_UNIT_KERJA'] - 1] || '');
          body.replaceText('(?i)\\{\\{NAMA_BARANG\\}\\}', targetAset[mapAset['NAMA_BARANG'] - 1] || targetAset[mapAset['JENIS_NAMA_BARANG'] - 1] || '');
          body.replaceText('(?i)\\{\\{KODE_BARANG\\}\\}', targetAset[mapAset['KODE_BARANG'] - 1] || '');
          body.replaceText('(?i)\\{\\{NIBAR\\}\\}', targetAset[mapAset['NIBAR'] - 1] || targetAset[mapAset['NOMOR_REGISTER'] - 1] || '');
          body.replaceText('(?i)\\{\\{MEREK\\}\\}', targetAset[mapAset['MERK_TYPE'] - 1] || '');
          body.replaceText('(?i)\\{\\{MERK_TYPE\\}\\}', targetAset[mapAset['MERK_TYPE'] - 1] || '');
          body.replaceText('(?i)\\{\\{UKURAN\\}\\}', targetAset[mapAset['UKURAN_CC'] - 1] || '');
          body.replaceText('(?i)\\{\\{BAHAN\\}\\}', targetAset[mapAset['BAHAN'] - 1] || '');
          body.replaceText('(?i)\\{\\{TAHUN_PEROLEHAN\\}\\}', String(targetAset[mapAset['TAHUN'] - 1] || targetAset[mapAset['TAHUN_PEROLEHAN'] - 1] || ''));
          body.replaceText('(?i)\\{\\{TAHUN\\}\\}', String(targetAset[mapAset['TAHUN'] - 1] || targetAset[mapAset['TAHUN_PEROLEHAN'] - 1] || ''));
          body.replaceText('(?i)\\{\\{NOMOR_RANGKA\\}\\}', targetAset[mapAset['NO_RANGKA'] - 1] || targetAset[mapAset['NO_RANGKA_SN'] - 1] || '');
          body.replaceText('(?i)\\{\\{NOMOR_MESIN\\}\\}', targetAset[mapAset['NO_MESIN'] - 1] || '');
          body.replaceText('(?i)\\{\\{NOMOR_POLISI\\}\\}', targetAset[mapAset['NO_POLISI'] - 1] || '');
          body.replaceText('(?i)\\{\\{NOMOR_BPKB\\}\\}', targetAset[mapAset['NO_BPKB'] - 1] || '');
          body.replaceText('(?i)\\{\\{NO_POLISI_RANGKA\\}\\}', payload.type === 'kendaraan' ? (targetAset[mapAset['NO_POLISI'] - 1] || '-') : (targetAset[mapAset['NOMOR_REGISTER'] - 1] || '-'));
          body.replaceText('(?i)\\{\\{NAMA_PEJABAT\\}\\}', targetPej[mapPejabat['nama_pejabat'] - 1] || '');
          body.replaceText('(?i)\\{\\{NIP_PEJABAT\\}\\}', targetPej[mapPejabat['nip'] - 1] || '');
          body.replaceText('(?i)\\{\\{JABATAN_PEJABAT\\}\\}', targetPej[mapPejabat['jabatan'] - 1] || '');

          // --- FITUR BARU: INJEKSI FOTO KE DALAM DOCX (UKURAN ABSOLUT CM) ---
          var arrTags = [
            { tag: '(?i)\\{\\{foto_kendaraan\\}\\}', url: targetAset[mapAset['FOTO_KENDARAAN'] - 1] || '', type: 'kendaraan' },
            { tag: '(?i)\\{\\{foto_stnk\\}\\}', url: targetAset[mapAset['FOTO_STNK'] - 1] || '', type: 'stnk' },
            { tag: '(?i)\\{\\{foto_pajak\\}\\}', url: targetAset[mapAset['FOTO_PAJAK'] - 1] || '', type: 'pajak' },
            { tag: '(?i)\\{\\{foto_peralatan\\}\\}', url: targetAset[mapAset['FOTO_BARANG'] - 1] || '', type: 'peralatan' }
          ];

          arrTags.forEach(function (itemTag) {
            var element = body.findText(itemTag.tag);
            if (element) {
              var textObj = element.getElement().asText();
              var actualUrl = itemTag.url;
              if (actualUrl && typeof actualUrl === 'string' && actualUrl.trim().startsWith('[')) {
                try {
                  var arrUrl = JSON.parse(actualUrl);
                  if (arrUrl && arrUrl.length > 0) {
                    actualUrl = arrUrl[arrUrl.length - 1].url;
                  }
                } catch (e) {
                  // Abaikan jika gagal parse
                }
              }

              if (actualUrl && actualUrl.indexOf('drive.google.com') !== -1) {
                try {
                  var fileIdMatch = actualUrl.match(/[-\w]{25,}/);
                  if (fileIdMatch && fileIdMatch[0]) {
                    var imgBlob = DriveApp.getFileById(fileIdMatch[0]).getBlob();
                    var parent = textObj.getParent();
                    if (parent.getType() === DocumentApp.ElementType.PARAGRAPH) {
                      var img = parent.asParagraph().insertInlineImage(element.getStartOffset(), imgBlob);

                      // SCALE PROPORTIONALLY TO MAINTAIN ASPECT RATIO
                      var origW = img.getWidth();
                      var origH = img.getHeight();
                      if (origW > 0 && origH > 0) {
                        if (itemTag.type === 'kendaraan' || itemTag.type === 'peralatan' || itemTag.type === 'mesin' || itemTag.type === 'penghapusan-kendaraan' || itemTag.type === 'penghapusan-mesin' || itemTag.type === 'alkes' || itemTag.type === 'penghapusan-alkes') {
                          var maxW = 263;
                          var maxH = 370;
                          var ratio = Math.min(maxW / origW, maxH / origH);
                          img.setWidth(Math.round(origW * ratio));
                          img.setHeight(Math.round(origH * ratio));
                        } else if (itemTag.type === 'stnk' || itemTag.type === 'pajak') {
                          var maxW = 428; // ~ 15.11 cm
                          var maxH = 285; // ~ 10.08 cm
                          var ratio = Math.min(maxW / origW, maxH / origH);
                          img.setWidth(Math.round(origW * ratio));
                          img.setHeight(Math.round(origH * ratio));
                        }
                      } else {
                        if (itemTag.type === 'kendaraan' || itemTag.type === 'peralatan' || itemTag.type === 'mesin' || itemTag.type === 'penghapusan-kendaraan' || itemTag.type === 'penghapusan-mesin' || itemTag.type === 'alkes' || itemTag.type === 'penghapusan-alkes') {
                          img.setWidth(263);
                          img.setHeight(370);
                        } else if (itemTag.type === 'stnk' || itemTag.type === 'pajak') {
                          img.setWidth(428);
                          img.setHeight(263);
                        }
                      }
                    }
                  }
                } catch (e) {
                  // Abaikan jika gambar gagal ditarik
                }
              }
              textObj.replaceText(itemTag.tag, ''); // Hapus teks tag kurung kurawalnya
            }
          });
          // ---------------------------------------------------------------

          tempDoc.saveAndClose();

          // Ubah ke format PDF dan beri nama file individual
          var pdfBlob = tempFile.getAs('application/pdf');
          var namaPeminjamText = targetAset[mapAset['NAMA'] - 1] || assetId;
          var seqNum = index + 1;
          var matchId = String(assetId).match(/\d+$/);
          if (matchId) {
            seqNum = parseInt(matchId[0], 10);
          }
          var tglStr = Utilities.formatDate(new Date(), Session.getScriptTimeZone(), "yyyy-MM-dd");
          pdfBlob.setName(seqNum + '. Dokumen_' + docNameFull + '_' + namaPeminjamText + '_' + tglStr + '.pdf');

          pdfBlobs.push(pdfBlob); // Kumpulkan file
          tempFile.setTrashed(true);

          // Masukkan ke history dokumen
          var newDocId = 'DOC-' + Utilities.getUuid().split('-')[0];
          shDoc.appendRow([
            newDocId, payload.type, assetId, docNameFull, "BATCH-ZIP", new Date().toISOString().substring(0, 10),
            targetAset[mapAset['NAMA'] - 1], targetAset[mapAset['NIP'] - 1],
            targetAset[mapAset['UNIT_KERJA'] - 1] || targetAset[mapAset['ORGANISASI_UNIT_KERJA'] - 1] || '',
            targetPej[mapPejabat['nama_pejabat'] - 1], 'ZIP ' + payload.actionType.toUpperCase(),
            '', session.username, new Date().toISOString()
          ]);
        }
      });
    } catch (err) {
      return { success: false, message: 'Gagal memproses pembuatan file DOCX: ' + err.message };
    }
  } else {
    return { success: false, message: 'Fitur ZIP khusus hanya bisa digunakan pada Master Word (.DOCX).' };
  }

  if (pdfBlobs.length === 0) {
    return { success: false, message: 'Tidak ada dokumen yang berhasil dibuat untuk disatukan dalam ZIP.' };
  }

  // --- ZIPPING ENGINE (Menyatukan file dan masuk ke Folder Otomatis) ---
  var timeStr = new Date().getTime().toString().slice(-6);
  var assetCategory = getAssetCategoryByType(payload.type);
  var zipName = "ASET_" + docNameFull.replace(/ /g, '_') + "_" + assetCategory + "_" + timeStr + ".zip";
  var zipBlob = Utilities.zip(pdfBlobs, zipName);

  // Buat folder APLIKASI ASET / Laporan_ZIP 
  var ssFile = DriveApp.getFileById(ss.getId());
  var parentFolder = ssFile.getParents().next();

  var zipFolderIter = parentFolder.getFoldersByName("Laporan_ZIP");
  var zipFolder = zipFolderIter.hasNext() ? zipFolderIter.next() : parentFolder.createFolder("Laporan_ZIP");

  var finalZipFile = zipFolder.createFile(zipBlob);
  finalZipFile.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);

  logAction(session.username, 'GENERATE_ZIP', 'Mencetak ' + pdfBlobs.length + ' aset ke ZIP via ' + payload.actionType.toUpperCase());

  // --- UBAH: Tambahkan pengiriman zipId untuk keperluan Direct Download ---
  return { success: true, zipUrl: finalZipFile.getUrl(), zipId: finalZipFile.getId() };
}
// ==========================================
// = FITUR BARU: AMBIL HISTORI DOKUMEN (CEGAH DOUBLE)
// ==========================================
function getAssetDocHistory(token, type) {
  var session = validateSession(token);
  if (!session.valid) return { success: false };

  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var shDoc = ss.getSheetByName('Dokumen');
    if (!shDoc || shDoc.getLastRow() <= 1) return { success: true, data: {} };

    var data = shDoc.getRange(2, 1, shDoc.getLastRow() - 1, shDoc.getLastColumn()).getValues();
    var mapD = getColumnMap(shDoc);
    var history = {};

    for (var i = 0; i < data.length; i++) {
      if (String(data[i][mapD['jenis_aset'] - 1]).toLowerCase() === type.toLowerCase()) {
        var aId = data[i][mapD['asset_id'] - 1];
        var dType = data[i][mapD['jenis_dokumen'] - 1];
        var url = data[i][mapD['file_pdf_url'] - 1];

        if (url && url.length > 10) {
          if (!history[aId]) history[aId] = {};
          history[aId][dType] = url; // Menindih dgn URL terbaru di baris paling bawah
        }
      }
    }
    return { success: true, data: history };
  } catch (e) {
    return { success: false, message: e.message };
  }
}

