// = FITUR BARU: API PELAPORAN PEMERIKSAAN
// ==========================================
function getPemeriksaanData(token) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  var ss = SpreadsheetApp.getActiveSpreadsheet();

  // Ambil Data Motor
  var dataMotor = [];
  var sheetMotor = ss.getSheetByName('Pemeriksaan');
  if (sheetMotor && sheetMotor.getLastRow() > 1) {
    var rawMotor = sheetMotor.getRange(2, 1, sheetMotor.getLastRow() - 1, sheetMotor.getLastColumn()).getValues();
    var mapMotor = getColumnMap(sheetMotor);
    dataMotor = rawMotor.map(function (row) {
      var obj = { type: 'motor' };
      for (var key in mapMotor) {
        var cellVal = row[mapMotor[key] - 1];
        obj[key] = (cellVal instanceof Date) ? cellVal.toISOString() : cellVal;
      }
      return obj;
    });
  }

  // Ambil Data Mobil
  var dataMobil = [];
  var sheetMobil = ss.getSheetByName('Pemeriksaan_Mobil');
  if (sheetMobil && sheetMobil.getLastRow() > 1) {
    var rawMobil = sheetMobil.getRange(2, 1, sheetMobil.getLastRow() - 1, sheetMobil.getLastColumn()).getValues();
    var mapMobil = getColumnMap(sheetMobil);
    dataMobil = rawMobil.map(function (row) {
      var obj = { type: 'mobil' };
      for (var key in mapMobil) {
        var cellVal = row[mapMobil[key] - 1];
        obj[key] = (cellVal instanceof Date) ? cellVal.toISOString() : cellVal;
      }
      return obj;
    });
  }

  return { success: true, data: dataMotor.concat(dataMobil) };
}

function savePemeriksaanKendaraan(token, payload) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  var lock = LockService.getScriptLock();
  try {
    lock.waitLock(10000);
    var ss = SpreadsheetApp.getActiveSpreadsheet();

    // 1. Simpan Foto jika ada
    var dateString = Utilities.formatDate(new Date(), "Asia/Jakarta", "dd-MM-yyyy");
    if (payload.foto_lampiran && payload.foto_lampiran.base64) {
      var folderParent = getOrCreateFolder(DriveApp.getRootFolder(), "SI_ASET_UPLOADS");
      var lampiranFotoFolder = getOrCreateFolder(folderParent, "Lampiran foto");
      var kendaraanFolder = getOrCreateFolder(lampiranFotoFolder, "Lampiran_foto_kendaraan");
      var pemeriksaanFolder = getOrCreateFolder(kendaraanFolder, "foto_pemeriksaan");

      var dataStr = payload.foto_lampiran.base64.split(',')[1];
      var ext = ".jpg";
      if (payload.foto_lampiran.mimeType.indexOf("png") !== -1) ext = ".png";

      var fileName = "foto_pemeriksaan_" + payload.plat_nomor + "_" + dateString + ext;
      var blob = Utilities.newBlob(Utilities.base64Decode(dataStr), payload.foto_lampiran.mimeType, fileName);
      var file = pemeriksaanFolder.createFile(blob);
      file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
      var fotoUrl = file.getUrl();

      // Update kolom FOTO_KENDARAAN di sheet Kendaraan
      var sheetKendaraan = ss.getSheetByName('Kendaraan');
      if (sheetKendaraan && sheetKendaraan.getLastRow() > 1) {
        var kendData = sheetKendaraan.getDataRange().getValues();
        var nopolIdx = kendData[0].indexOf('NO_POLISI');
        var fotoIdx = kendData[0].indexOf('FOTO_KENDARAAN');
        if (nopolIdx !== -1 && fotoIdx !== -1) {
          for (var i = 1; i < kendData.length; i++) {
            if (kendData[i][nopolIdx] === payload.plat_nomor) {
              var oldVal = kendData[i][fotoIdx];
              sheetKendaraan.getRange(i + 1, fotoIdx + 1).setValue(appendToHistory(oldVal, fotoUrl, dateString));
              break;
            }
          }
        }
      }
    }

    // 2. Simpan ke Pemeriksaan atau Pemeriksaan_Mobil
    var sheetName = payload.jenis_form === 'motor' ? 'Pemeriksaan' : 'Pemeriksaan_Mobil';
    var sheet = ss.getSheetByName(sheetName);
    if (!sheet) {
      setupDatabase();
      sheet = ss.getSheetByName(sheetName);
      if (!sheet) {
        return { success: false, message: 'Sheet ' + sheetName + ' gagal dibuat.' };
      }
    }

    var map = getColumnMap(sheet);
    var isEdit = !!payload.edit_id;
    var id = isEdit ? payload.edit_id : 'CHK-' + new Date().getTime();
    var rowValues = new Array(sheet.getLastColumn());
    var sheetData = sheet.getDataRange().getValues();
    var rowIndex = -1;

    if (isEdit) {
      var idIdx = map['id'] - 1;
      for (var j = 1; j < sheetData.length; j++) {
        if (sheetData[j][idIdx] === payload.edit_id) {
          rowIndex = j + 1;
          break;
        }
      }
    }

    for (var key in map) {
      if (key === 'id') {
        rowValues[map[key] - 1] = id;
      } else if (key === 'waktu' || key === 'created_at') {
        if (isEdit && rowIndex !== -1) {
          rowValues[map[key] - 1] = sheetData[rowIndex - 1][map[key] - 1]; // Keep original
        } else {
          rowValues[map[key] - 1] = new Date().toISOString();
        }
      } else {
        var cleanVal = payload[key] !== undefined ? payload[key] : '';
        rowValues[map[key] - 1] = sanitizeInput(cleanVal, 2000);
      }
    }

    if (isEdit && rowIndex !== -1) {
      sheet.getRange(rowIndex, 1, 1, rowValues.length).setValues([rowValues]);
      logAction(session.username, 'UPDATE_PEMERIKSAAN', 'Update Pemeriksaan ' + sheetName + ': ' + payload.plat_nomor);
    } else {
      sheet.appendRow(rowValues);
      logAction(session.username, 'ADD_PEMERIKSAAN', 'Pemeriksaan ' + sheetName + ': ' + payload.plat_nomor);
    }

    return { success: true };
  } catch (err) {
    return { success: false, message: 'Error: ' + err.message };
  } finally {
    lock.releaseLock();
  }
}

function getPelaporan(token) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getSheetByName('PelaporanPemeriksaan');
  if (!sheet || sheet.getLastRow() <= 1) return { success: true, data: [] };

  var data = sheet.getRange(2, 1, sheet.getLastRow() - 1, sheet.getLastColumn()).getValues();
  var map = getColumnMap(sheet);

  var result = data.map(function (row) {
    var obj = {};
    for (var key in map) {
      var cellVal = row[map[key] - 1];
      obj[key] = (cellVal instanceof Date) ? cellVal.toISOString() : cellVal;
    }
    return obj;
  });

  return { success: true, data: result };
}

function savePelaporan(token, payload) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  var lock = LockService.getScriptLock();
  try {
    lock.waitLock(10000);
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheet = ss.getSheetByName('PelaporanPemeriksaan');
    if (!sheet) {
      setupDatabase();
      sheet = ss.getSheetByName('PelaporanPemeriksaan');
    }
    var map = getColumnMap(sheet);
    var lastRow = sheet.getLastRow();

    var id = payload.id;
    var rowToEdit = -1;

    if (id) {
      var idColValues = sheet.getRange(2, 1, lastRow - 1, 1).getValues();
      for (var i = 0; i < idColValues.length; i++) {
        if (idColValues[i][0] === id) {
          rowToEdit = i + 2;
          break;
        }
      }
    }

    var isEdit = rowToEdit !== -1;
    var finalRow = isEdit ? rowToEdit : lastRow + 1;

    if (!isEdit) {
      id = 'LPR-' + new Date().getTime();
    }

    var rowValues = new Array(sheet.getLastColumn());
    for (var key in map) {
      if (key === 'id') rowValues[map[key] - 1] = id;
      else if (key === 'created_at') rowValues[map[key] - 1] = isEdit ? sheet.getRange(rowToEdit, map['created_at']).getValue() : new Date().toISOString();
      else if (key === 'updated_at') rowValues[map[key] - 1] = new Date().toISOString();
      else {
        var cleanVal = payload[key] !== undefined ? payload[key] : '';
        rowValues[map[key] - 1] = sanitizeInput(cleanVal, 2000); // allow long data
      }
    }

    sheet.getRange(finalRow, 1, 1, rowValues.length).setValues([rowValues]);
    logAction(session.username, isEdit ? 'UPDATE_PELAPORAN' : 'ADD_PELAPORAN', 'Pelaporan Pemeriksaan: ' + id);
    return { success: true };
  } catch (err) {
    return { success: false, message: 'Gagal mengunci: ' + err.message };
  } finally {
    lock.releaseLock();
  }
}

function deletePelaporan(token, id) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  var ss = SpreadsheetApp.getActiveSpreadsheet();

  var sheets = ['Pemeriksaan', 'Pemeriksaan_Mobil', 'PelaporanPemeriksaan'];
  for (var s = 0; s < sheets.length; s++) {
    var sheet = ss.getSheetByName(sheets[s]);
    if (sheet && sheet.getLastRow() > 1) {
      var data = sheet.getRange(2, 1, sheet.getLastRow() - 1, 1).getValues();
      for (var i = 0; i < data.length; i++) {
        if (data[i][0] === id) {
          sheet.deleteRow(i + 2);
          logAction(session.username, 'DELETE_PELAPORAN', 'Menghapus pelaporan: ' + id);
          return { success: true };
        }
      }
    }
  }

  return { success: false, message: 'Data tidak ditemukan.' };
}

// ==========================================
// = FITUR BARU: GENERATE PDF DOKUMEN PEMERIKSAAN
// ==========================================
function generatePemeriksaanDocPDF(token, payload) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var shPemeriksaan = ss.getSheetByName(payload.docTypeCode === 'Pemeriksaan Motor' ? 'Pemeriksaan' : 'Pemeriksaan_Mobil');
  var shPelaporan = ss.getSheetByName('PelaporanPemeriksaan');
  var shTmpl = ss.getSheetByName('TemplateDokumen');

  // Cari Template
  var mapTmpl = getColumnMap(shTmpl);
  var dataTmpl = shTmpl.getLastRow() > 1 ? shTmpl.getRange(2, 1, shTmpl.getLastRow() - 1, shTmpl.getLastColumn()).getValues() : [];
  var activeTemplateContent = null;
  for (var i = 0; i < dataTmpl.length; i++) {
    var row = dataTmpl[i];
    var jenisTmpl = row[mapTmpl['jenis_template'] - 1];
    var jenisAset = row[mapTmpl['jenis_aset'] - 1];
    var namaTmpl = (row[mapTmpl['nama_template'] - 1] || '').toUpperCase();

    // Check if either jenis_aset or jenis_template matches payload.docTypeCode exactly
    if (jenisTmpl === payload.docTypeCode || jenisAset === payload.docTypeCode) {
      activeTemplateContent = row[mapTmpl['isi_template'] - 1];
      break;
    }

    // Fallback logic by name if user misconfigured dropdowns
    if (payload.docTypeCode === 'Pemeriksaan Motor' && namaTmpl.indexOf('MOTOR') !== -1) {
      activeTemplateContent = row[mapTmpl['isi_template'] - 1];
    }
    if (payload.docTypeCode === 'Pemeriksaan Mobil' && namaTmpl.indexOf('MOBIL') !== -1) {
      activeTemplateContent = row[mapTmpl['isi_template'] - 1];
    }
  }

  if (!activeTemplateContent) {
    return { success: false, message: 'Template dokumen untuk jenis ' + payload.docTypeCode + ' belum diatur.' };
  }

  var isDocxMode = !activeTemplateContent.includes('<') && activeTemplateContent.length > 20;

  try {
    var mapPelaporan = getColumnMap(shPelaporan);
    var dataPelaporan = shPelaporan.getLastRow() > 1 ? shPelaporan.getRange(2, 1, shPelaporan.getLastRow() - 1, shPelaporan.getLastColumn()).getValues() : [];

    var mapPemeriksaan = getColumnMap(shPemeriksaan);
    var dataPemeriksaan = shPemeriksaan.getLastRow() > 1 ? shPemeriksaan.getRange(2, 1, shPemeriksaan.getLastRow() - 1, shPemeriksaan.getLastColumn()).getValues() : [];

    // Setup Folder
    var ssFile = DriveApp.getFileById(ss.getId());
    var parentFolder = ssFile.getParents().next();

    var rootReportFolderIter = parentFolder.getFoldersByName("DOKUMEN PEMERIKSAAN");
    var rootReportFolder = rootReportFolderIter.hasNext() ? rootReportFolderIter.next() : parentFolder.createFolder("DOKUMEN PEMERIKSAAN");

    var folderName = payload.docTypeCode === 'Pemeriksaan Motor' ? 'SEPEDA MOTOR' : 'MOBIL';
    var specificFolderIter = rootReportFolder.getFoldersByName(folderName);
    var specificFolder = specificFolderIter.hasNext() ? specificFolderIter.next() : rootReportFolder.createFolder(folderName);

    var finalPdfUrls = [];

    payload.assetIds.forEach(function (pelaporanId) {
      // Find Pemeriksaan directly
      var targetPemeriksaan = null;
      var targetRowIndex = -1;
      for (var j = 0; j < dataPemeriksaan.length; j++) {
        if (dataPemeriksaan[j][mapPemeriksaan['id'] - 1] === pelaporanId) {
          targetPemeriksaan = dataPemeriksaan[j];
          targetRowIndex = j;
          break;
        }
      }

      if (targetPemeriksaan) {
        var platNomorTarget = String(targetPemeriksaan[mapPemeriksaan['plat_nomor'] - 1] || '').trim();
        var rawDateObj = targetPemeriksaan[mapPemeriksaan['waktu'] - 1];
        if (!(rawDateObj instanceof Date)) {
          rawDateObj = new Date(rawDateObj || new Date());
        }
        var tglJam = rawDateObj.toLocaleDateString('id-ID', { year: 'numeric', month: 'long', day: 'numeric' });
        var bulanArray = ["Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];
        var bulanPemeriksaan = bulanArray[rawDateObj.getMonth()] || '';
        var tanggalPeriksa = rawDateObj.getDate() + " " + bulanPemeriksaan + " " + rawDateObj.getFullYear();
        var pj = targetPemeriksaan[mapPemeriksaan['penanggung_jawab'] - 1] || '';
        var newFileName = 'Pemeriksaan_kendaraan_' + pj + '_' + (new Date().toISOString().slice(0, 10));

        // Rebuild kesimpulan dynamically from checkboxes
        var masalah = [];
        var keysToCheck = ['double_stater', 'klakson', 'indikator', 'lampu_utama', 'lampu_rem', 'lampu_belok', 'kondisi_plat', 'spion', 'foot_step', 'tutup_angin', 'lampu_hazard', 'lampu_sign', 'sirine', 'klakson_mobil', 'spidometer', 'ind_lampu_haza', 'ind_lampu_sign', 'ind_rem_tangan', 'ind_oli', 'ind_check_engine', 'ind_fuel', 'ind_sabuk', 'ind_suhu', 'ind_pintu', 'kondisi_ban', 'ac_mobil', 'wiper', 'kebersihan'];
        keysToCheck.forEach(function (k) {
          if (mapPemeriksaan[k]) {
            var val = String(targetPemeriksaan[mapPemeriksaan[k] - 1] || '').toLowerCase();
            if (val.indexOf('mati') !== -1 || val.indexOf('rusak') !== -1 || val.indexOf('tidak') !== -1 || val.indexOf('hilang') !== -1) {
              masalah.push(k.replace(/_/g, ' '));
            }
          }
        });
        var kesimpulanText = masalah.length > 0 ? ('Perhatian: Masalah pada ' + masalah.join(', ')) : 'Aman, Kondisi Baik';

        // Get foto_kendaraan blob from Kendaraan sheet
        var fotoBlob = null;
        try {
          var shKendaraan = ss.getSheetByName('Kendaraan');
          var mapK = getColumnMap(shKendaraan);
          var dataK = shKendaraan.getLastRow() > 1 ? shKendaraan.getRange(2, 1, shKendaraan.getLastRow() - 1, shKendaraan.getLastColumn()).getValues() : [];
          var latestFotoUrl = '';
          for (var k = 0; k < dataK.length; k++) {
            if (String(dataK[k][mapK['NO_POLISI'] - 1]) === platNomorTarget) {
              var histStr = dataK[k][mapK['FOTO_KENDARAAN'] - 1];
              if (histStr) {
                try {
                  var arr = JSON.parse(histStr);
                  if (arr.length > 0) latestFotoUrl = arr[arr.length - 1].url;
                } catch (e) { latestFotoUrl = histStr; }
              }
              break;
            }
          }
          if (latestFotoUrl) {
            var idMatch = latestFotoUrl.match(/[-\w]{25,}/);
            if (idMatch) {
              fotoBlob = DriveApp.getFileById(idMatch[0]).getBlob();
            }
          }
        } catch (e) { }

        if (isDocxMode) {
          var templateFile = DriveApp.getFileById(activeTemplateContent);
          var tempFile = templateFile.makeCopy('TEMP_DOC_' + pelaporanId);
          var tempDoc = DocumentApp.openById(tempFile.getId());
          var body = tempDoc.getBody();

          body.replaceText('(?i)\\{\\{PLAT_NOMOR\\}\\}', String(platNomorTarget || ''));
          body.replaceText('(?i)\\{\\{NOMOOR_PLAT\\}\\}', String(platNomorTarget || ''));
          body.replaceText('(?i)\\{\\{PENANGGUNG_JAWAB\\}\\}', String(pj));
          body.replaceText('(?i)\\{\\{TANGGAL_JAM\\}\\}', String(tglJam));
          body.replaceText('(?i)\\{\\{TANGGAL_PERIKSA\\}\\}', String(tanggalPeriksa));
          body.replaceText('(?i)\\{\\{BULAN_PEMERIKSAAN\\}\\}', String(bulanPemeriksaan));
          body.replaceText('(?i)\\{\\{KESIMPULAN\\}\\}', String(kesimpulanText));

          if (targetPemeriksaan) {
            // Custom Mapping Mobil
            body.replaceText('(?i)\\{\\{JENIS_KENDARAAN\\}\\}', String(targetPemeriksaan[mapPemeriksaan['jenis_kendaraan'] - 1] || ''));
            body.replaceText('(?i)\\{\\{SIRINE_MOBIL\\}\\}', String(targetPemeriksaan[mapPemeriksaan['sirine'] - 1] || ''));
            body.replaceText('(?i)\\{\\{KLAKSON_MOBIL\\}\\}', String(targetPemeriksaan[mapPemeriksaan['klakson_mobil'] - 1] || ''));
            body.replaceText('(?i)\\{\\{PNL_SPIDOMETER\\}\\}', String(targetPemeriksaan[mapPemeriksaan['spidometer'] - 1] || ''));
            body.replaceText('(?i)\\{\\{PNL_HAZARD\\}\\}', String(targetPemeriksaan[mapPemeriksaan['ind_lampu_haza'] - 1] || ''));
            body.replaceText('(?i)\\{\\{PNL_LAMPU_SIGN\\}\\}', String(targetPemeriksaan[mapPemeriksaan['ind_lampu_sign'] - 1] || ''));
            body.replaceText('(?i)\\{\\{INDIKATOR_REM\\}\\}', String(targetPemeriksaan[mapPemeriksaan['ind_rem_tangan'] - 1] || ''));
            body.replaceText('(?i)\\{\\{INDIKATOR_OLI\\}\\}', String(targetPemeriksaan[mapPemeriksaan['ind_oli'] - 1] || ''));
            body.replaceText('(?i)\\{\\{INDIKATOR_ENGINE\\}\\}', String(targetPemeriksaan[mapPemeriksaan['ind_check_engine'] - 1] || ''));
            body.replaceText('(?i)\\{\\{INDIKATOR_FUEL\\}\\}', String(targetPemeriksaan[mapPemeriksaan['ind_fuel'] - 1] || ''));
            body.replaceText('(?i)\\{\\{INDIKATOR_SABUK\\}\\}', String(targetPemeriksaan[mapPemeriksaan['ind_sabuk'] - 1] || ''));
            body.replaceText('(?i)\\{\\{INDIKATOR_SUHU\\}\\}', String(targetPemeriksaan[mapPemeriksaan['ind_suhu'] - 1] || ''));
            body.replaceText('(?i)\\{\\{INDIKATOR_PINTU\\}\\}', String(targetPemeriksaan[mapPemeriksaan['ind_pintu'] - 1] || ''));
            body.replaceText('(?i)\\{\\{PLAT_MOTOR\\}\\}', String(targetPemeriksaan[mapPemeriksaan['kondisi_plat'] - 1] || ''));
            body.replaceText('(?i)\\{\\{WIPER_MOBIL\\}\\}', String(targetPemeriksaan[mapPemeriksaan['wiper'] - 1] || ''));

            // Custom Mapping Motor
            body.replaceText('(?i)\\{\\{DOUBLE_STARTER\\}\\}', String(targetPemeriksaan[mapPemeriksaan['double_stater'] - 1] || ''));
            body.replaceText('(?i)\\{\\{INDIKATOR_KENDARAAN\\}\\}', String(targetPemeriksaan[mapPemeriksaan['indikator'] - 1] || ''));
            body.replaceText('(?i)\\{\\{LAMPU_SEIN\\}\\}', String(targetPemeriksaan[mapPemeriksaan['lampu_belok'] - 1] || ''));
            body.replaceText('(?i)\\{\\{SPOIN\\}\\}', String(targetPemeriksaan[mapPemeriksaan['spion'] - 1] || ''));
          }

          // Dynamic tags based on all columns in the Pemeriksaan sheet (to catch any we missed)
          if (targetPemeriksaan) {
            for (var key in mapPemeriksaan) {
              if (key === 'id' || key === 'waktu' || key === 'created_at') continue; // Skip internal columns
              var tagValue = targetPemeriksaan[mapPemeriksaan[key] - 1] || '';
              var tagPlaceholder = '(?i)\\{\\{' + key.toUpperCase() + '\\}\\}';
              body.replaceText(tagPlaceholder, String(tagValue));
            }
          }

          // Insert Image logic!
          if (fotoBlob) {
            var imgPlaceholder = body.findText('(?i)\\{\\{foto_kendaraan\\}\\}');
            if (imgPlaceholder) {
              var el = imgPlaceholder.getElement().getParent();
              if (el.getType() === DocumentApp.ElementType.PARAGRAPH) {
                var inlineImg = el.asParagraph().insertInlineImage(0, fotoBlob);
                var maxW = 300; // max width 300px
                if (inlineImg.getWidth() > maxW) {
                  inlineImg.setHeight(Math.round(inlineImg.getHeight() * (maxW / inlineImg.getWidth())));
                  inlineImg.setWidth(maxW);
                }
              }
              imgPlaceholder.getElement().setText(''); // remove tag text
            }
          } else {
            body.replaceText('(?i)\\{\\{foto_kendaraan\\}\\}', '- Tidak ada foto -');
          }

          tempDoc.saveAndClose();

          var blob = tempFile.getAs(MimeType.PDF);
          var pdfFile = specificFolder.createFile(blob).setName(newFileName + ".pdf");
          pdfFile.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);

          finalPdfUrls.push({ id: pelaporanId, url: pdfFile.getUrl() });
          tempFile.setTrashed(true);
        } else {
          // HTML Template
          var htmlOutput = activeTemplateContent;
          htmlOutput = htmlOutput.replace(new RegExp('#PLAT_NOMOR', 'g'), platNomorTarget || '');
          htmlOutput = htmlOutput.replace(new RegExp('#PENANGGUNG_JAWAB', 'g'), pj);
          htmlOutput = htmlOutput.replace(new RegExp('#TANGGAL_JAM', 'g'), tglJam);
          htmlOutput = htmlOutput.replace(new RegExp('#KESIMPULAN', 'g'), kesimpulanText);

          if (targetPemeriksaan) {
            for (var key in mapPemeriksaan) {
              if (key === 'id' || key === 'waktu' || key === 'created_at') continue;
              var tagValue = targetPemeriksaan[mapPemeriksaan[key] - 1] || '';
              htmlOutput = htmlOutput.replace(new RegExp('#' + key.toUpperCase(), 'g'), String(tagValue));
            }
          }

          var htmlContent = "<!DOCTYPE html><html><head><style>body { font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif; }</style></head><body>" + htmlOutput + "</body></html>";
          var blob = Utilities.newBlob(htmlContent, MimeType.HTML, "temp.html").getAs(MimeType.PDF);
          var pdfFile = specificFolder.createFile(blob).setName(newFileName + ".pdf");
          pdfFile.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);

          finalPdfUrls.push({ id: pelaporanId, url: pdfFile.getUrl() });
        }
      }
    });

    // Save URLs to Pemeriksaan / Pemeriksaan_Mobil sheet
    try {
      var mapP = getColumnMap(shPemeriksaan);

      // If dokumen_url column doesn't exist, create it
      if (!mapP['dokumen_url']) {
        var lc = shPemeriksaan.getLastColumn();
        shPemeriksaan.getRange(1, lc + 1).setValue('dokumen_url');
        mapP['dokumen_url'] = lc + 1;
      }

      var dataP = shPemeriksaan.getLastRow() > 1 ? shPemeriksaan.getRange(2, 1, shPemeriksaan.getLastRow() - 1, shPemeriksaan.getLastColumn()).getValues() : [];

      finalPdfUrls.forEach(function (pdfData) {
        for (var i = 0; i < dataP.length; i++) {
          if (dataP[i][mapP['id'] - 1] === pdfData.id) {
            shPemeriksaan.getRange(i + 2, mapP['dokumen_url']).setValue(pdfData.url);
            break;
          }
        }
      });
    } catch (e) { }

    return { success: true, pdfUrls: finalPdfUrls };

  } catch (err) {
    return { success: false, message: 'Gagal generate Pemeriksaan PDF: ' + err.message };
  }
}

// ==========================================
// = FITUR BARU: GENERATE ZIP PELAPORAN (UPDATE)
// ==========================================
function generatePemeriksaanZip(token, payload) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  // Generate the PDF first, then put them in a ZIP
  var resPdf = generatePemeriksaanDocPDF(token, payload);
  if (!resPdf.success) return resPdf;

  var blobs = [];
  resPdf.pdfUrls.forEach(function (item) {
    var fileId = item.url.match(/[\w-]{33,}/);
    if (fileId && fileId.length > 0) {
      var file = DriveApp.getFileById(fileId[0]);
      blobs.push(file.getBlob());
    }
  });

  var timeStr = new Date().getTime().toString().slice(-6);
  var zipName = "Laporan_Pemeriksaan_ZIP_" + timeStr + ".zip";
  var zipBlob = Utilities.zip(blobs, zipName);

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var ssFile = DriveApp.getFileById(ss.getId());
  var parentFolder = ssFile.getParents().next();
  var zipFolderIter = parentFolder.getFoldersByName("Laporan_ZIP");
  var zipFolder = zipFolderIter.hasNext() ? zipFolderIter.next() : parentFolder.createFolder("Laporan_ZIP");

  var finalZipFile = zipFolder.createFile(zipBlob);
  finalZipFile.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);

  logAction(session.username, 'GENERATE_ZIP', 'Mencetak ' + payload.assetIds.length + ' pelaporan pemeriksaan ke ZIP.');
  return { success: true, zipUrl: finalZipFile.getUrl() };
}

// ==========================================
// = FITUR BARU: GENERATE ZIP PELAPORAN
// ==========================================
function generatePelaporanZip(token, ids) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getSheetByName('PelaporanPemeriksaan');
  if (!sheet || sheet.getLastRow() <= 1) return { success: false, message: 'Tidak ada data pelaporan.' };

  var data = sheet.getRange(2, 1, sheet.getLastRow() - 1, sheet.getLastColumn()).getValues();
  var map = getColumnMap(sheet);

  var selectedData = [];
  for (var i = 0; i < data.length; i++) {
    var row = data[i];
    var id = row[map['id'] - 1];
    if (ids.indexOf(id) !== -1) {
      selectedData.push(row);
    }
  }

  if (selectedData.length === 0) {
    return { success: false, message: 'Data yang dipilih tidak ditemukan.' };
  }

  var blobs = [];

  // Create CSV Content
  var csvLines = [];
  var headers = ['No', 'Tanggal/Jam', 'Nama Pemeriksa', 'NIP/Jabatan', 'Detail Kendaraan', 'Kesimpulan', 'URL Lampiran'];
  csvLines.push(headers.map(function (h) { return '"' + h.replace(new RegExp('"', 'g'), '""') + '"'; }).join(','));

  for (var i = 0; i < selectedData.length; i++) {
    var row = selectedData[i];
    var tgl = row[map['tanggal_jam'] - 1];
    if (tgl instanceof Date) tgl = tgl.toISOString();

    var line = [
      (i + 1),
      tgl,
      row[map['nama_pemeriksa'] - 1],
      row[map['nip_jabatan'] - 1],
      row[map['detail_kendaraan'] - 1],
      row[map['kesimpulan'] - 1],
      row[map['foto_lampiran'] - 1] || ''
    ];
    csvLines.push(line.map(function (val) { return '"' + String(val).replace(new RegExp('"', 'g'), '""') + '"'; }).join(','));

    // Optionally fetch image
    var fotoUrl = row[map['foto_lampiran'] - 1];
    if (fotoUrl && fotoUrl.toString().trim().length > 10) {
      try {
        var resp = UrlFetchApp.fetch(fotoUrl, { muteHttpExceptions: true });
        if (resp.getResponseCode() === 200) {
          var imgBlob = resp.getBlob();
          imgBlob.setName("Lampiran_" + row[map['id'] - 1] + "_" + (i + 1) + ".jpg");
          blobs.push(imgBlob);
        }
      } catch (e) {
        // ignore fetch error
      }
    }
  }

  var csvBlob = Utilities.newBlob(csvLines.join('\n'), 'text/csv', 'Rekap_Pemeriksaan.csv');
  blobs.push(csvBlob);

  var timeStr = new Date().getTime().toString().slice(-6);
  var zipName = "Pelaporan_Pemeriksaan_" + timeStr + ".zip";
  var zipBlob = Utilities.zip(blobs, zipName);

  var ssFile = DriveApp.getFileById(ss.getId());
  var parentFolder = ssFile.getParents().next();
  var zipFolderIter = parentFolder.getFoldersByName("Laporan_ZIP");
  var zipFolder = zipFolderIter.hasNext() ? zipFolderIter.next() : parentFolder.createFolder("Laporan_ZIP");

  var finalZipFile = zipFolder.createFile(zipBlob);
  finalZipFile.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);

  logAction(session.username, 'GENERATE_ZIP', 'Mencetak ' + selectedData.length + ' pelaporan ke ZIP.');
  return { success: true, zipUrl: finalZipFile.getUrl() };
}

// --- FITUR BARU: BACA ISI FOLDER UNTUK REKAPITULASI ---
function getRekapitulasiData(token, type) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheetName = getSheetNameByType(type);
    var sheet = ss.getSheetByName(sheetName);
    if (!sheet) return { success: true, data: [] };

    var data = sheet.getDataRange().getValues();
    if (data.length <= 1) return { success: true, data: [] };

    var headers = data[0];
    var map = {};
    for (var i = 0; i < headers.length; i++) {
      map[headers[i].trim()] = i + 1;
    }

    var folderCache = {
      'Berita Acara': [],
      'Pakta Integritas': [],
      'Daftar Peminjam': [],
      'Daftar Penandatangan': [],
      'Master Data': []
    };

    var ssFile = DriveApp.getFileById(ss.getId());
    var parentFolder = ssFile.getParents().next();
    var catFolder = getFolderByType(type);
    var rootIter = parentFolder.getFoldersByName(catFolder);

    if (rootIter.hasNext()) {
      var rootFolder = rootIter.next();
      var docTypes = ['Berita Acara', 'Pakta Integritas', 'Daftar Peminjam', 'Daftar Penandatangan', 'Master Data ' + sheetName];
      docTypes.forEach(function (dt) {
        var key = dt.indexOf('Master Data') !== -1 ? 'Master Data' : dt;
        var subIter = rootFolder.getFoldersByName(dt);
        if (subIter.hasNext()) {
          var files = subIter.next().getFiles();
          while (files.hasNext()) {
            folderCache[key].push(files.next().getName());
          }
        }
      });
    }

    var result = [];
    var mdExists = folderCache['Master Data'].length > 0;

    for (var i = 1; i < data.length; i++) {
      var row = data[i];
      var namaPeminjam = String(row[map['NAMA'] - 1] || row[map['id'] - 1] || '');

      var x = {
        NAMA: row[map['NAMA'] - 1],
        NIP: row[map['NIP'] - 1],
        NAMA_BARANG: row[map['NAMA_BARANG'] - 1],
        JENIS_NAMA_BARANG: row[map['JENIS_NAMA_BARANG'] - 1],
        MERK_TYPE: row[map['MERK_TYPE'] - 1],
        NO_POLISI: row[map['NO_POLISI'] - 1],
        NOMOR_REGISTER: row[map['NOMOR_REGISTER'] - 1],
        NIBAR: row[map['NIBAR'] - 1]
      };

      x.HAS_MD = mdExists;

      // Untuk dokumen personal, kita cek nama file di dalam foldernya persis mengandung nama peminjam
      x.HAS_BA = namaPeminjam ? folderCache['Berita Acara'].some(function (fn) { return fn.indexOf(namaPeminjam) !== -1; }) : false;
      x.HAS_PI = namaPeminjam ? folderCache['Pakta Integritas'].some(function (fn) { return fn.indexOf(namaPeminjam) !== -1; }) : false;

      // Untuk dokumen batch (DP & DT), kita fallback ke database ATAU jika foldernya tidak kosong 
      var linkDP = row[map['LINK_DP'] - 1] || '';
      x.HAS_DP = linkDP.toString().length > 5 && folderCache['Daftar Peminjam'].length > 0;

      var linkDT = row[map['LINK_DT'] - 1] || '';
      x.HAS_DT = linkDT.toString().length > 5 && folderCache['Daftar Penandatangan'].length > 0;

      result.push(x);
    }

    return { success: true, data: result };
  } catch (e) {
    return { success: false, message: e.message };
  }
}


function updateUserPermissions(token, targetUsername, permissionsString) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };
  if (session.user.role !== 'Admin') return { success: false, message: 'Akses ditolak. Hanya Admin.' };

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getSheetByName('Users');
  var data = sheet.getDataRange().getValues();
  var headers = data[0];
  var uIdx = headers.indexOf('username');
  var permIdx = headers.indexOf('permissions');

  if (permIdx === -1) {
    sheet.getRange(1, headers.length + 1).setValue('permissions');
    permIdx = headers.length;
  }

  for (var i = 1; i < data.length; i++) {
    if (String(data[i][uIdx]).toLowerCase() === targetUsername.toLowerCase()) {
      sheet.getRange(i + 1, permIdx + 1).setValue(permissionsString);
      logAction(session.user.username, 'UPDATE_PERMISSIONS', 'Memperbarui hak akses menu untuk user: ' + targetUsername);
      return { success: true, message: 'Hak akses berhasil diperbarui.' };
    }
  }
  return { success: false, message: 'User tidak ditemukan.' };
}


// ==========================================
// = FITUR: GET EXISTING PDF BASE64 UNTUK CETAK GABUNGAN
// ==========================================
function getExistingPdfBase64(token, payload) {
  try {
    var session = validateSession(token);
    if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheetName = '';
    if (payload.type === 'kendaraan') sheetName = 'Kendaraan';
    else if (payload.type === 'mesin') sheetName = 'Peralatan dan Mesin';
    else if (payload.type === 'alkes') sheetName = 'Alkes';
    else if (payload.type === 'penghapusan-alkes') sheetName = 'Penghapusan Alkes';
    else if (payload.type === 'penghapusan-kendaraan') sheetName = 'Penghapusan Kendaraan';
    else if (payload.type === 'penghapusan-mesin') sheetName = 'Penghapusan Peralatan dan Mesin';
    else sheetName = 'Peralatan';
    
    // Khusus untuk pelaporan pemeriksaan
    if (payload.type === 'pelaporan-pemeriksaan') {
      sheetName = 'Pelaporan Pemeriksaan';
    }

    var sh = ss.getSheetByName(sheetName);
    if (!sh) return { success: false, message: 'Sheet tidak ditemukan.' };

    var mapCol = getColumnMap(sh);
    var data = sh.getRange(2, 1, sh.getLastRow() - 1, sh.getLastColumn()).getValues();
    
    var colLink = '';
    if (payload.type === 'pelaporan-pemeriksaan') {
       colLink = mapCol['LINK_PDF']; // Asumsi jika ada link pdf pelaporan, atau sesuaikan
    } else {
       colLink = payload.docTypeCode === 'BA' ? mapCol['LINK_BA'] : (payload.docTypeCode === 'PI' ? mapCol['LINK_PI'] : '');
    }

    if (!colLink) {
       return { success: false, message: 'Kolom link dokumen tidak ditemukan di database.' };
    }

    var pdfsBase64 = [];
    var notFoundCount = 0;

    payload.assetIds.forEach(function (assetId) {
      var foundUrl = '';
      for (var i = 0; i < data.length; i++) {
        // Kolom ID biasanya di mapCol['id'] atau mapCol['ID']
        var idCol = mapCol['id'] || mapCol['ID'] || 1;
        if (String(data[i][idCol - 1]) === String(assetId)) {
          foundUrl = data[i][colLink - 1];
          break;
        }
      }

      if (foundUrl && typeof foundUrl === 'string' && foundUrl.indexOf('drive.google.com') !== -1) {
        var match = foundUrl.match(/[-\w]{25,}/);
        if (match && match[0]) {
          try {
            var file = DriveApp.getFileById(match[0]);
            var blob = file.getBlob();
            var b64 = Utilities.base64Encode(blob.getBytes());
            pdfsBase64.push(b64);
          } catch (e) {
             notFoundCount++;
          }
        } else {
          notFoundCount++;
        }
      } else {
        notFoundCount++;
      }
    });

    if (pdfsBase64.length === 0) {
      return { success: false, message: 'Tidak ada dokumen PDF yang ditemukan. Pastikan Anda sudah membuat laporan (Buat Laporan) untuk data yang dipilih terlebih dahulu.' };
    }
    
    if (notFoundCount > 0) {
      // Boleh dikasih warning tapi tetap lanjut
    }

    return { success: true, pdfs: pdfsBase64 };
  } catch (e) {
    return { success: false, message: e.toString() };
  }
}


// ==========================================
// FITUR: KALIBRASI ALAT KESEHATAN
// ==========================================

function ensureKalibrasiSheet(ss) {
  var sheet = ss.getSheetByName('Kalibrasi_Alkes');
  if (!sheet) {
    sheet = ss.insertSheet('Kalibrasi_Alkes');
    var headers = ['ID_Kalibrasi', 'ID_Alkes', 'Nama_Alat', 'Tanggal_Pengajuan', 'Vendor_Teknisi', 'Tanggal_Selesai', 'Status', 'Catatan_Hasil', 'Foto_Pelaksanaan', 'Sertifikat_Kalibrasi', 'Biaya_Kalibrasi'];
    sheet.getRange(1, 1, 1, headers.length).setValues([headers]);
    sheet.getRange(1, 1, 1, headers.length).setFontWeight('bold');
    sheet.setFrozenRows(1);
  }
  return sheet;
}

function getKalibrasiData(token) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheet = ensureKalibrasiSheet(ss);
    
    var lastRow = sheet.getLastRow();
    if (lastRow <= 1) return { success: true, data: [] };

    var data = sheet.getRange(2, 1, lastRow - 1, sheet.getLastColumn()).getValues();
    var headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];
    
    var result = data.map(function(row) {
      var obj = {};
      headers.forEach(function(h, index) { obj[h] = row[index]; });
      return obj;
    });

    return { success: true, data: result };
  } catch (e) {
    return { success: false, message: e.toString() };
  }
}

function savePengajuanKalibrasi(token, payload) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheet = ensureKalibrasiSheet(ss);
    
    var newId = 'KAL-' + Utilities.getUuid().split('-')[0].toUpperCase();
    
    sheet.appendRow([
      newId,
      payload.id_alkes,
      payload.nama_alat,
      payload.tgl_pengajuan,
      payload.vendor,
      payload.tgl_estimasi || '',
      'Pengajuan',
      '',
      '',
      ''
    ]);
    
    // Opsional: Update status di sheet Alkes menjadi 'Sedang Dikalibrasi'
    var sheetAlkes = ss.getSheetByName('Alkes');
    if (sheetAlkes) {
      var dataAlkes = sheetAlkes.getDataRange().getValues();
      var idIdx = dataAlkes[0].indexOf('id');
      var kondisiIdx = dataAlkes[0].indexOf('KONDISI_STATUS');
      if (idIdx !== -1 && kondisiIdx !== -1) {
        for (var i = 1; i < dataAlkes.length; i++) {
          if (String(dataAlkes[i][idIdx]) === String(payload.id_alkes)) {
            sheetAlkes.getRange(i + 1, kondisiIdx + 1).setValue('Sedang Dikalibrasi');
            break;
          }
        }
      }
    }

    logAction(session.username, 'KALIBRASI_PENGAJUAN', 'Mengajukan kalibrasi untuk alat: ' + payload.nama_alat);
    return { success: true };
  } catch (e) {
    return { success: false, message: e.toString() };
  }
}

function savePenyelesaianKalibrasi(token, payload) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheet = ensureKalibrasiSheet(ss);
    
    // 1. Upload File ke Drive
    var ssFile = DriveApp.getFileById(ss.getId());
    var parentFolder = ssFile.getParents().next();
    var rootFolder = getOrCreateFolder(parentFolder, 'APLIKASI ASET');
    var alkesFolder = getOrCreateFolder(rootFolder, 'DATA ALKES');
    var targetFolder = getOrCreateFolder(alkesFolder, 'Pengajuan Kalibrasi');
    
    var timeStr = new Date().getTime().toString().slice(-6);
    var namaAlatSafe = payload.id_alkes.replace(/[^a-zA-Z0-9_-]/g, '');
    
    var fotoUrl = '';
    var pdfUrl = '';
    
    if (payload.foto && payload.foto.base64) {
      var blobF = Utilities.newBlob(Utilities.base64Decode(payload.foto.base64), payload.foto.mimeType, 'FOTO_KALIBRASI_' + namaAlatSafe + '_' + timeStr + '.jpg');
      fotoUrl = targetFolder.createFile(blobF).setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW).getUrl();
    }
    if (payload.pdf && payload.pdf.base64) {
      var blobP = Utilities.newBlob(Utilities.base64Decode(payload.pdf.base64), payload.pdf.mimeType, 'SERTIFIKAT_KALIBRASI_' + namaAlatSafe + '_' + timeStr + '.pdf');
      pdfUrl = targetFolder.createFile(blobP).setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW).getUrl();
    }

    // 2. Update Row di Kalibrasi_Alkes
    var dataK = sheet.getDataRange().getValues();
    var idKIdx = dataK[0].indexOf('ID_Kalibrasi');
    var foundK = false;
    
    for (var i = 1; i < dataK.length; i++) {
      if (String(dataK[i][idKIdx]) === String(payload.id_kalibrasi)) {
        sheet.getRange(i + 1, dataK[0].indexOf('Tanggal_Selesai') + 1).setValue(payload.tgl_selesai);
        sheet.getRange(i + 1, dataK[0].indexOf('Status') + 1).setValue('Selesai');
        sheet.getRange(i + 1, dataK[0].indexOf('Catatan_Hasil') + 1).setValue(payload.catatan);
        sheet.getRange(i + 1, dataK[0].indexOf('Foto_Pelaksanaan') + 1).setValue(fotoUrl);
        sheet.getRange(i + 1, dataK[0].indexOf('Sertifikat_Kalibrasi') + 1).setValue(pdfUrl);
        
        var biayaIdx = dataK[0].indexOf('Biaya_Kalibrasi');
        if (biayaIdx === -1) {
          // Jika kolom Biaya_Kalibrasi belum ada, tambahkan
          sheet.getRange(1, sheet.getLastColumn() + 1).setValue('Biaya_Kalibrasi');
          biayaIdx = sheet.getLastColumn() - 1;
        }
        sheet.getRange(i + 1, biayaIdx + 1).setValue(payload.biaya_kalibrasi || 0);

        foundK = true;
        break;
      }
    }

    // 3. Update status di sheet Alkes menjadi 'Baik'
    var sheetAlkes = ss.getSheetByName('Alkes');
    if (sheetAlkes) {
      var dataAlkes = sheetAlkes.getDataRange().getValues();
      var idIdx = dataAlkes[0].indexOf('id');
      var kondisiIdx = dataAlkes[0].indexOf('KONDISI_STATUS');
      if (idIdx !== -1 && kondisiIdx !== -1) {
        for (var i = 1; i < dataAlkes.length; i++) {
          if (String(dataAlkes[i][idIdx]) === String(payload.id_alkes)) {
            sheetAlkes.getRange(i + 1, kondisiIdx + 1).setValue('Baik');
            break;
          }
        }
      }
    }

    logAction(session.username, 'KALIBRASI_SELESAI', 'Menyelesaikan kalibrasi ID: ' + payload.id_kalibrasi);
    return { success: true };
  } catch (e) {
    return { success: false, message: e.toString() };
  }
}
